const CL = {"periods":[[1,"D-1년","1년 전 ~ 6달 전"],[2,"D-6달","6달 전 ~ 1달 전"],[3,"D-1달","1달 전 ~ 8일 전"],[4,"D-7","7일 전 ~ 2일 전"],[5,"D-1","전날"],[6,"D-day","당일"],[7,"식 후","부록"]],"items":[{"n":"1-01","id":"A-002","p":1,"k":"must","c":[],"b":"w","s":-400,"d":-300,"when":"","name":"결혼식 방향 정하기","desc":"어떤 결혼식을 할지, 무엇을 가장 중요하게 볼지 둘이 먼저 정해요.","opts":"일반 예식 · 스몰웨딩 · 예식 없이","tips":["예산 한도와 \"이것만은 꼭\" 하나를 정해 두면 예식장·스드메·예물을 같은 기준으로 고를 수 있어요."]},{"n":"1-02","id":"A-009","p":1,"k":"opt","c":[],"b":"w","s":-365,"d":-300,"when":"","name":"준비 일정표·예산표 만들기","desc":"둘이 같이 보는 일정표와 예산표를 하나 만들어요.","yes":"업체마다 다른 계약금·잔금 날짜와 각자 부담금을 한 장에서 볼 수 있어요.","no":"잔금 날짜와 부담금을 계약서마다 따로 찾아봐야 해요. 할 일 순서는 이 체크리스트로 볼 수 있어요.","opts":"엑셀 · 노션 · 웨딩 앱 · 이 체크리스트"},{"n":"1-03","id":"A-004","p":1,"k":"must","c":[],"b":"w","s":-400,"d":-270,"when":"","name":"예상 하객 수 잡기","desc":"양가 하객이 대략 몇 명일지 숫자만 먼저 잡아요. 이름 명단은 나중에 써요.","opts":"양가 대략 숫자 · 규모 구간(100명 이하, 300명 이상 등)","tips":["대략의 숫자만 있어도 예식장 상담에서 보증 인원과 홀 크기를 바로 이야기할 수 있어요."]},{"n":"1-04","id":"A-012","p":1,"k":"must","c":[],"b":"w","s":-400,"d":-270,"when":"","name":"예식장 후보 고르고 투어하기","desc":"후보 예식장에 직접 가서 위치·식사·주차·홀 분위기를 비교해요.","opts":"호텔 · 컨벤션(일반 웨딩홀) · 채플 · 하우스·스몰 · 야외 · 공공 예식장","tips":["대관료·식대 견적을 미리 받아 가면 비교가 쉬워요. 하루에 2~3곳을 보는 경우가 많아요.","투어 때 하객석에 직접 앉아 무대가 잘 보이는지, 자리가 몇 개인지 보세요."],"links":[{"label":"서울시 공공 예식장 \"더 아름다운 결혼식\" (지역마다 제도가 달라요)","url":"https://wedding.seoulwomen.or.kr/","note":"","extra":"","date":"2026-11-13"},{"label":"지역별 예식장 가격 (한국소비자원 참가격 › 결혼서비스)","url":"https://www.price.go.kr","note":"","extra":"","date":"2026-11-13"}]},{"n":"1-05","id":"A-001","p":1,"k":"must","c":[],"b":"w","s":-400,"d":-240,"when":"","name":"양가 부모님께 결혼 알리기","desc":"각자 부모님께 먼저 알리고, 그다음 상대 부모님께 인사드려요.","tips":["이게 끝나야 상견례 날짜와 양가 참석 인원을 맞출 수 있어요."]},{"n":"1-06","id":"A-003","p":1,"k":"must","c":[],"b":"w","s":-400,"d":-240,"when":"","name":"결혼식 예산·분담 정하기","desc":"결혼식에 쓸 총액과 양가·두 사람이 나눌 몫을 정해요.","opts":"총액 먼저 정하고 나누기 · 양가 지원 범위 확인 · 각자 부담금 적기","tips":["총액을 먼저 정하고 항목별로 나눠 보세요. 혼주 한복·혼주 메이크업·하객 버스처럼 처음 계획에 없던 항목이 붙었다는 후기가 있어요.","이렇게 덧붙는 항목은 목록으로 만들어 누가 낼지까지 미리 정해 두세요."]},{"n":"1-07","id":"A-005","p":1,"k":"must","c":[],"b":"w","s":-400,"d":-240,"when":"","name":"예식 시기·날짜·시간대 정하기","desc":"계절·요일·시간대를 고르고 날짜 후보를 2~3개 정해요.","opts":"성수기(3~6월·9~12월) · 비수기(1·2·7·8월) · 토요일 낮 · 일요일 · 평일","tools":["date"],"tips":["비수기(1·2·7·8월)와 평일은 같은 홀도 비용이 낮은 편이에요. 토요일 점심은 1년 전에도 마감되기 쉬워요."]},{"n":"1-08","id":"A-006","p":1,"k":"opt","c":[],"b":"w","s":-400,"d":-240,"when":"","name":"택일 확인 (손 없는 날·사주)","desc":"날짜 후보를 전통 길일 기준으로도 한 번 봐요.","yes":"날짜 후보를 고를 때 전통 길일 기준을 더할 수 있어요.","no":"예식장 빈 날과 두 분·부모님이 원하는 날로만 정해요.","opts":"손 없는 날 달력 보기 · 택일 맡기기","tools":["date"]},{"n":"1-09","id":"A-010","p":1,"k":"must","c":[],"b":"w","s":-365,"d":-240,"when":"","name":"상견례","desc":"양가 가족이 처음 만나 결혼 일정과 방향을 맞춰요. 예식장 계약과 같은 시기에 하는 경우도 많아요.","opts":"장소 — 룸 있는 한정식 · 호텔 다이닝 · 코스 레스토랑 / 시간 — 점심 · 이른 저녁","tips":["식당은 2~3주 전에 예약하고, 식사비를 낼 쪽을 미리 정해 두세요. 예단·비용 분담 같은 이야기는 둘이 먼저 정해 가면 그 자리가 편했다는 후기가 있어요."]},{"n":"1-10","id":"A-011","p":1,"k":"must","c":[],"b":"w","s":-365,"d":-240,"when":"","name":"예단·예물·폐백 할지 양가와 정하기","desc":"전통 절차 중 무엇을 할지 양가가 미리 맞춰요.","opts":"모두 함 · 일부만(반지만, 폐백만 등) · 모두 생략 · 현금으로 대신","tips":["\"모두 생략\"으로 정해도 한쪽 부모님이 예물을 따로 준비하시면, 다른 쪽도 맞춰 준비하게 됐다는 후기가 있어요. 그런 이야기가 나오면 답하기 전에 다른 쪽 부모님과 먼저 맞춰 보세요.","할 것과 안 할 것을 한 줄씩 적어 양가가 같이 보세요."]},{"n":"1-11","id":"A-013","p":1,"k":"must","c":[],"b":"w","s":-365,"d":-240,"when":"","name":"예식장 계약","desc":"날짜를 확정하고 계약서를 꼼꼼히 확인해요.","opts":"원하는 날짜 · 남은 시간대(비수기·잔여 타임)","tips":["계약서에서 꼭 볼 것 — 보증 인원(양가 따로인지, 나중에 줄일 수 있는지), 1인 식대와 초과 인원 식대, 대관료, 꽃장식·연출, 봉사료·부가세 포함 여부, 위약금·환불, 날짜 변경, 예식 간격, 폐백실, 주차, 식권 방식, 외부 업체(스냅·답례품) 반입.","위약금·환불은 웨딩홀마다 달라요. 2025년 11월부터 예식장은 요금·위약금·환급 기준을 계약서 맨 앞 장(표지)에 적어야 하니, 서명 전에 그 장부터 읽어 보세요.","당일 계약 할인처럼 조건이 붙은 계약에는 환불이 안 된다는 특약이 들어가기도 해요. 특약 칸까지 읽고 서명하세요."],"links":[{"label":"지역별 예식장 가격 (한국소비자원 참가격 › 결혼서비스)","url":"https://www.price.go.kr","note":"","extra":"","date":"2026-11-13"}]},{"n":"1-12","id":"A-027","p":1,"k":"must","c":[],"b":"w","s":-365,"d":-240,"when":"","name":"사회자 섭외","desc":"예식장 날짜가 정해지면 바로 사회자를 정해요.","opts":"전문 사회자 · 지인 사회자 · 예식장 연계 사회자","mc":"인기 있는 날짜는 사회자 일정도 먼저 차요. 날짜가 정해지면 바로 물어보세요.","mcDraft":true,"kakao":true,"tips":["사회자에게 식순과 축가·이벤트 순서를 미리 알려 주세요. 당일 진행이 그 순서로 짜여요."]},{"n":"1-13","id":"A-029","p":1,"k":"opt","c":[],"b":"w","s":-365,"d":-240,"when":"","name":"전문 축가 섭외","desc":"축가를 전문 가수에게 맡길지 정하고 섭외해요. 친구에게 부탁하는 지인 축가는 D-6달에 따로 있어요.","yes":"곡 선정·연습·음향까지 맡길 수 있어요.","no":"지인 축가만 하거나 축가 없이 진행해요.","opts":"솔로 · 듀엣·팀 · 라이브 세션 · 지인 1곡 + 전문 1곡","mc":"축가 순서와 곡 길이를 사회자에게도 미리 알려 주세요. 앞뒤 멘트를 거기에 맞춰요.","mcDraft":true},{"n":"1-14","id":"B-001","p":1,"k":"must","c":[],"b":"w","s":-365,"d":-240,"when":"","name":"결혼 자금 전체 계획","desc":"결혼식·신혼집·혼수·신혼여행에 쓸 총액과 돈이 나올 곳을 한 표로 정리해요.","opts":"돈이 나올 곳 — 모은 돈 · 양가 지원 · 정책 대출 · 은행 대출 / 나누는 법 — 반반 · 소득 비율 · 항목별로 맡기","tips":["결혼 비용에서 가장 큰 몫은 신혼집이라는 조사가 있어요. 대출이 필요한지 이때 알면 집 구하기 일정을 미리 잡을 수 있어요."]},{"n":"1-15","id":"A-007","p":1,"k":"must","c":[],"b":"w","s":-365,"d":-210,"when":"","name":"준비 방식 정하기 (플래너·직접)","desc":"플래너와 함께할지, 직접 계약할지 정해요.","opts":"동행 플래너 · 비동행 플래너 · 직접 계약","tips":["플래너마다 함께해 주는 범위가 달라요. 계약 전에 드레스 투어·촬영·본식 날 동행처럼 어디까지 해 주는지 물어보세요.","같은 업체를 직접 견적과 플래너 견적으로 둘 다 받아 비교해 보세요. 비용 차이가 크지 않았다는 후기가 있어요.","플래너 업체는 공정위 결혼준비대행업 표준약관을 쓰는 곳인지 물어보세요."],"links":[{"label":"결혼준비대행 계약 해지·환급 기준 (생활법령정보)","url":"https://m.easylaw.go.kr/MOB/CsmInfoRetrieve.laf?csmSeq=1894&ccfNo=2&cciNo=3&cnpClsNo=1","note":"","extra":"","date":"2026-11-13"}]},{"n":"1-16","id":"A-008","p":1,"k":"opt","c":[],"b":"w","s":-365,"d":-210,"when":"","name":"웨딩박람회 가기","desc":"여러 업체를 한곳에서 상담해요.","yes":"하루에 여러 업체 견적을 비교할 수 있어요.","no":"업체를 하나씩 찾아가거나 플래너를 통해 비교해요.","opts":"상담만 하고 오기 · 현장 계약","tips":["현장에서 계약하기 전에 청약철회 기간을 꼭 물어보세요. 박람회를 어디서 열었는지에 따라 철회 기준이 달라요."],"links":[{"label":"박람회·온라인 계약 청약철회 (생활법령정보)","url":"https://m.easylaw.go.kr/MOB/CsmInfoRetrieve.laf?csmSeq=1894&ccfNo=2&cciNo=3&cnpClsNo=1","note":"","extra":"","date":"2026-11-13"}]},{"n":"1-17","id":"A-014","p":1,"k":"opt","c":[],"b":"w","s":-365,"d":-210,"when":"","name":"본식 스냅 계약","desc":"예식 당일 사진을 찍을 작가를 정해요.","yes":"예식 당일 모습을 작가 사진으로 남겨요.","no":"아이폰 스냅으로 대신하기도 해요.","opts":"본식 스냅 작가 · 서브 스냅 추가 · 아이폰 스냅","tips":["계약할 때 컷 수, 원본을 얼마나 주는지, 수정 횟수, 원본·앨범 받는 날짜를 확인하세요.","스냅 업체는 계약 전에 사업자 정보를 확인하고, 계약금은 카드로 내세요. 당일 누가 찍으러 오는지도 미리 물어보세요."]},{"n":"1-18","id":"A-015","p":1,"k":"opt","c":[],"b":"w","s":-365,"d":-210,"when":"","name":"본식 영상 계약","desc":"예식 전체 영상과 짧은 하이라이트 영상을 찍을 업체를 정해요.","yes":"식 전체 흐름과 목소리까지 영상으로 남아요.","no":"스냅 사진만으로 충분하다고 보는 경우도 있어요.","opts":"전문 업체 · 감독 추가 · 하이라이트만","tips":["영상 길이와 받는 날짜를 계약서에서 확인하세요."]},{"n":"2-01","id":"A-016","p":2,"k":"must","c":[],"b":"w","s":-365,"d":-180,"when":"","name":"스드메 업체 계약","desc":"드레스·메이크업 업체를 계약해요. 스튜디오 촬영을 하면 스튜디오도 함께예요.","opts":"스드메 패키지 · 드메 패키지(촬영 빼고) · 업체별 따로","tips":["계약 전에 추가금이 붙는 항목을 꼭 물어보세요. 원본 파일, 앨범 페이지 추가, 드레스 피팅비, 헬퍼비, 원장·실장 지정비, 이른 시간 시작 비용, 헤어 변형비예요.","헬퍼비처럼 견적서에 없고 당일 현금으로 내는 항목이 있었다는 후기가 있어요. 계약 전에 추가금 항목표를 받아 예산에 같이 넣으세요."],"links":[{"label":"결혼준비대행 계약·위약금 기준 (생활법령정보)","url":"https://m.easylaw.go.kr/MOB/CsmInfoRetrieve.laf?csmSeq=1894&ccfNo=2&cciNo=3&cnpClsNo=1","note":"","extra":"","date":"2026-11-13"},{"label":"지역별 스드메 가격 (한국소비자원 참가격 › 결혼서비스)","url":"https://www.price.go.kr","note":"","extra":"","date":"2026-11-13"}]},{"n":"2-02","id":"B-002","p":2,"k":"auto","c":["trip=abroad,domestic"],"b":"t","s":-366,"d":-181,"when":"","who":"신혼여행 가는 커플","name":"신혼여행 여행지·시기 정하기","desc":"어디로, 언제, 얼마로 갈지와 출발일을 정해요.","opts":"시기 — 식 직후 · 몇 달 뒤 / 형태 — 여행사 패키지 · 항공·숙소 따로 / 지역 — 휴양지 · 도시·유럽 · 가까운 곳 · 국내","tips":["하와이처럼 숙박세·리조트피가 현지에서 따로 붙는 곳이 있어요. 예산에 같이 넣으세요."]},{"n":"2-03","id":"A+02","p":2,"k":"opt","c":[],"b":"w","s":-210,"d":-180,"when":"","name":"헤어·메이크업 시연 받기","desc":"메이크업샵을 정하기 전에 원하는 스타일이 나오는지 미리 받아 봐요.","yes":"계약 전에 스타일이 맞는지 확인할 수 있어요.","no":"촬영 메이크업 때 처음 확인하게 돼요.","opts":"유료 시연 · 촬영 메이크업으로 확인"},{"n":"2-04","id":"B-003","p":2,"k":"auto","c":["trip=abroad"],"b":"t","s":-366,"d":-151,"when":"","who":"해외 신혼여행","name":"여권 확인·재발급","desc":"여권 남은 기간, 영문 이름, 전자여권인지 확인해요.","opts":"지금 여권 그대로 · 재발급 · 새로 발급","tips":["항공권은 여권의 영문 이름으로 예약해요. 그래서 항공권보다 여권을 먼저 봐요. 나라마다 여권 남은 기간 조건이 있고, 미국은 전자여권만 돼요."],"links":[{"label":"외교부 여권안내 「재발급」","url":"https://www.passport.go.kr/home/kor/contents.do?menuPos=7","note":"","extra":"","date":"2026-11-13"}]},{"n":"2-05","id":"A-018","p":2,"k":"opt","c":[],"b":"w","s":-270,"d":-150,"when":"","name":"결혼반지·예물","desc":"결혼반지와 예물을 무엇으로, 어디서 할지 정해요.","yes":"예식 반지 교환과 웨딩 촬영에 반지를 쓸 수 있어요.","no":"식순에서 반지 교환을 빼요.","opts":"반지만 · 반지 + 시계 · 반지 + 주얼리·가방 / 사는 곳 — 종로 · 청담 · 백화점","tips":["일부 브랜드는 주문하고 받기까지 3달 넘게 걸려요. 촬영 때 끼려면 미리 주문하세요."]},{"n":"2-06","id":"A-017","p":2,"k":"def","c":[],"b":"w","s":-180,"d":-150,"when":"","who":"드레스를 빌리거나 사는 경우","name":"드레스 투어·드레스샵 정하기","desc":"드레스샵 2~3곳을 돌아보고 촬영·본식 드레스를 고를 샵을 정해요.","opts":"샵 2~3곳 투어 · 기성 드레스 구매","tips":["피팅 횟수와 초과 비용, 패키지에 든 드레스 등급과 업그레이드 비용을 글로 받아 두세요. 인기 샵은 피팅 예약이 빨리 차요.","투어 때 드레스 사진을 못 찍게 하는 샵이 많아요. 같이 간 사람에게 드레스마다 특징을 적거나 그려 달라고 부탁하세요."]},{"n":"2-07","id":"B-004","p":2,"k":"def","c":["trip=abroad"],"b":"t","s":-181,"d":-151,"when":"","who":"해외 신혼여행","name":"전자여행허가·비자 신청","desc":"가는 나라가 사전 허가나 비자를 요구하면 미리 신청해요.","opts":"공식 사이트·앱에서 직접 · 대행 사이트","linkHead":"나라별 확인할 곳","tips":["미국(하와이 포함)은 승인이 없으면 비행기를 탈 수 없어요. 항공권을 사기 전에 신청하세요. 공식 사이트가 아닌 대행 사이트는 수수료가 더 붙어요.","여권을 새로 받으면 ESTA도 다시 받아야 해요. 여권부터 정리하고 신청하세요."],"links":[{"label":"미국·하와이 ESTA","url":"https://www.cbp.gov/travel/international-visitors/esta","note":"","extra":"","date":"2026-11-13"},{"label":"괌·사이판","url":"https://www.0404.go.kr/bbs/contsPst/MST0000000000116/16/detail","note":"","extra":"","date":"2026-11-13"},{"label":"캐나다 eTA","url":"https://www.canada.ca/en/immigration-refugees-citizenship/services/visit-canada/eta/apply-ko.html","note":"","extra":"","date":"2026-11-13"},{"label":"호주 ETA","url":"https://southkorea.embassy.gov.au/seol/ETA601.html","note":"","extra":"","date":"2026-11-13"},{"label":"영국 ETA","url":"https://www.gov.uk/eta","note":"","extra":"","date":"2026-11-13"},{"label":"유럽(솅겐)","url":"https://home-affairs.ec.europa.eu/policies/schengen/smart-borders/european-travel-information-authorisation-system_en","note":"참고용 안내: 지금은 사전 허가가 필요 없어요. 유럽 여행 사전 허가(ETIAS)는 아직 시작 전이고, 시작 몇 달 전에 EU가 날짜를 알려요.","extra":"","date":"2026-11-13"}]},{"n":"2-08","id":"B-007","p":2,"k":"must","c":["home!=have"],"b":"h","s":-320,"d":-75,"when":"","name":"신혼집 지역·형태·예산 정하기","desc":"어디에, 어떤 형태로, 얼마짜리 집을 구할지 정해요.","opts":"매매 · 전세 · 반전세·월세 · 공공임대 · 살던 집에 합가 · 부모님 집","tips":["대출·청약·혼인신고 시기를 이 결정에 맞춰 정해요. 혼수도 집이 정해진 뒤 고르는 게 좋아요."]},{"n":"2-09","id":"B-008","p":2,"k":"auto","c":["home!=have","loan=yes,undecided"],"b":"h","s":-320,"d":-75,"when":"","who":"집 대출 받는 경우","name":"대출 자격·한도 알아보기","desc":"받을 수 있는 대출과 한도를 집 고르기 전에 알아봐요.","check":["신혼부부로 인정되는 기간 · 부부 합산 소득 기준과 1인 소득 예외 · 순자산 · 집 크기와 보증금 · 한도 · 신청 기한"],"opts":"신혼부부 전세자금(버팀목) · 신혼가구 구입자금(디딤돌) · 신생아 특례 · 은행 대출","tips":["한도를 알아야 볼 집의 가격대가 정해져요. 집 보러 다니기 전에 은행에 가서 대략적인 한도를 먼저 물어봤다(가심사)는 후기가 많아요."],"links":[{"label":"주택도시기금 신혼부부전용 전세자금","url":"https://nhuf.molit.go.kr/FP/FP05/FP0502/FP05020401.jsp","note":"","extra":"","date":"2026-11-13"},{"label":"주택도시기금 신혼부부전용 구입자금","url":"https://nhuf.molit.go.kr/FP/FP05/FP0503/FP05030601.jsp","note":"","extra":"","date":"2026-11-13"}]},{"n":"2-10","id":"B-006","p":2,"k":"auto","c":["trip=abroad,domestic"],"b":"t","s":-301,"d":-121,"when":"","who":"신혼여행 가는 커플","name":"항공·숙소 예약","desc":"항공권과 숙소, 또는 여행사 패키지를 예약해요.","opts":"여행사 패키지 · 항공·숙소 따로 · 항공만 예약하고 숙소는 현지에서","tips":["회사 휴가 날짜를 먼저 확정하고, 예약 전에 변경·환불 조건을 확인하세요. 미국은 ESTA를 먼저 받으세요.","식 당일이나 다음 날 떠나면 도착 첫날 일정은 비워 두세요. 식 당일에 떠났다가 많이 지쳤다는 후기가 있어요."]},{"n":"2-11","id":"B-020","p":2,"k":"must","c":[],"b":"h","s":-195,"d":-75,"when":"","name":"혼수 목록·예산 정하기","desc":"가전·가구·침구·주방용품 중 무엇을 살지, 예산은 얼마인지 정해요.","opts":"패키지 · 품목별 · 구독·렌탈 · 쓰던 것 가져오기","tips":["집 구조와 크기를 확인한 뒤 목록을 쓰세요. 먼저 산 가전이 집에 안 맞을 수 있어요.","전셋집에서 시작하면 곧 다시 이사할 수 있어요. 큰 가구는 꼭 필요한 것만 먼저 사고 살면서 채웠다는 후기가 있어요."]},{"n":"2-12","id":"B-032","p":2,"k":"auto","c":["job=both,one"],"b":"w","s":-240,"d":-120,"when":"","who":"직장인","name":"결혼 휴가·회사 경조금 신청","desc":"회사에 결혼 휴가와 경조금을 신청하고 날짜를 확정해요.","opts":"경조 휴가 · 연차 붙이기 · 회사 경조금 신청","tips":["결혼 휴가는 법으로 정한 휴가가 아니라 회사 규정으로 정해져요(공무원은 복무규정). 항공권을 예약하기 전에 휴가 날짜부터 확정하세요."]},{"n":"2-13","id":"B-010","p":2,"k":"auto","c":["home=apply"],"b":"w","s":-365,"d":-105,"when":"","who":"청약을 노리는 무주택 커플","name":"신혼부부 특별공급 청약 알아보기","desc":"분양 주택에 신혼부부 몫으로 청약할 수 있는지 알아봐요.","opts":"민영 신혼 특공 · 공공분양 · 신혼희망타운 · 신생아 특공","tips":["신혼부부 특별공급은 혼인신고일부터 센 혼인 기간 조건이 있어요. 예비 신혼부부는 공공분양·신혼희망타운에만 신청할 수 있고, 입주 전까지 혼인신고를 마쳐야 해요. 소득 기준은 넣으려는 단지 공고에서 확인하세요."],"links":[{"label":"청약홈 특별공급 안내","url":"https://www.applyhome.co.kr/ar/ara/selectSubscrptIntroSpetialView.do","note":"","extra":"","date":"2026-11-13"}]},{"n":"2-14","id":"B-009","p":2,"k":"choice","c":[],"b":"w","s":-180,"d":-105,"when":"","name":"혼인신고 시기 정하기","desc":"혼인신고를 식 전에 할지, 식 직후에 할지, 집·대출 일정 뒤에 할지 정해요.","check":["혼인세액공제·혼인지원금: 2027년부터 어떻게 될지 12월 국회에서 결정될 예정이에요.","부모님 지원금 증여 공제: 혼인신고일 앞뒤 기간에 받은 돈이 대상이에요.","정책 대출: 결혼 예정일 때도 둘의 소득을 합쳐서 봐요. 1인 소득 예외도 있어요. 결혼 예정자로 받으면 대출 뒤 정해진 기간 안에 혼인신고를 하고 서류를 내야 해요.","신혼부부 청약: 혼인신고일부터 센 혼인 기간 조건이 있어요."],"opts":"식 전 · 식 직후 · 집·대출 일정 뒤","tips":["세금 공제·증여 공제와 신혼부부 청약의 혼인 기간은 예식일이 아니라 혼인신고일로 세요. 정책 대출과 공공분양 청약은 결혼 예정일 때도 신청할 수 있어요. 신고하면 날짜를 바꿀 수 없으니 아래를 확인하고 정하세요.","혼인신고 날짜를 은행 대출 상담을 받아 본 뒤에 정했다는 후기가 있어요."],"links":[{"label":"국세청 혼인세액공제","url":"https://www.nts.go.kr/nts/cm/cntnts/cntntsView.do?cntntsId=7875","note":"","extra":"","date":"2026-11-13"},{"label":"상속세및증여세법 제53조의2","url":"https://www.law.go.kr/법령/상속세및증여세법/제53조의2","note":"","extra":"","date":"2026-11-13"},{"label":"주택도시기금","url":"https://nhuf.molit.go.kr/FP/FP05/FP0502/FP05020401.jsp","note":"","extra":"","date":"2026-11-13"}],"choices":[["before","식 전"],["after","식 직후"],["later","집·대출 일정 뒤"],["und","아직 몰라요"]]},{"n":"2-15","id":"A+01","p":2,"k":"auto","c":["a:2-18!=no"],"b":"w","s":-130,"d":-100,"when":"","who":"스튜디오 촬영하는 경우","name":"촬영용 드레스 고르기·피팅","desc":"스튜디오 촬영에 입을 드레스를 고르고 입어 봐요.","tips":["촬영 장소와 콘셉트에 맞춰 여러 벌을 골라요."]},{"n":"2-16","id":"A-020","p":2,"k":"opt","c":[],"b":"w","s":-180,"d":-90,"when":"","name":"피부·몸 관리 시작","desc":"예식에 맞춰 피부·몸 관리를 언제부터 할지 정하고 시작해요.","yes":"관리할 시간을 넉넉히 둘 수 있어요. 예를 들면 100일 전 눈가, 70일 전 치아 미백, 50일 전 보습, 30일 전 손 관리 순서예요.","no":"평소 관리대로 가요. 예식 전날엔 새 시술과 강한 제품을 피하세요.","opts":"홈케어 · 피부과·관리실 · 치아 미백"},{"n":"2-17","id":"A-021","p":2,"k":"must","c":[],"b":"w","s":-180,"d":-90,"when":"","name":"신랑 예복 준비","desc":"촬영과 본식에 입을 신랑 예복을 빌리거나 맞추거나 사요.","opts":"대여 · 맞춤 · 기성 구매 · 촬영은 대여 + 본식은 맞춤","tips":["맞춤은 가봉·수선까지 1~2달 넘게 걸려요. 촬영 때 입으려면 촬영 날짜에서 거꾸로 세어 주문하세요.","셔츠·넥타이·구두·벨트·긴 검정 양말도 같이 챙기세요.","셔츠 안에는 보통 속옷을 입지 않아서 니플패치가 꼭 필요해요."]},{"n":"2-18","id":"A-022","p":2,"k":"opt","c":[],"b":"w","s":-180,"d":-90,"when":"","name":"스튜디오(웨딩) 촬영","desc":"결혼 전에 스튜디오나 야외에서 웨딩 사진을 찍어요.","yes":"모바일 청첩장·식전영상·포토테이블에 쓸 사진이 생겨요.","no":"촬영 없이 드레스·메이크업만 계약하는 커플도 늘고 있어요.","opts":"스튜디오 · 야외 스냅 · 셀프 웨딩 촬영","tips":["촬영 시안을 작가와 미리 나누고, 의상마다 헤어를 정해 두세요. 푼 머리에서 묶은 머리 순서가 편해요.","촬영 날짜를 잡으면 반지·예복처럼 만드는 데 오래 걸리는 것부터 거꾸로 일정을 세우세요."]},{"n":"2-19","id":"A-025","p":2,"k":"opt","c":[],"b":"w","s":-180,"d":-90,"when":"","name":"혼주 한복·부모님 의상","desc":"양가 어머님 한복과 부모님 예복을 정하고 예약해요.","yes":"양가 어머님 한복 색을 맞출 수 있어요. 같이 고르실지 따로 고르실지 먼저 여쭤보세요.","no":"한복 대신 양장·정장을 입으셔도 돼요.","opts":"한복 대여 · 한복 맞춤 · 양장","tips":["맞춤은 시간이 더 걸려요. 사진 말고 실물을 얼굴에 대 보고 고르세요. 대여는 기본 구성에 무엇이 들었는지 확인하세요. 받는 날은 예식 1주 전 무렵이에요."]},{"n":"2-20","id":"A-034","p":2,"k":"opt","c":[],"b":"w","s":-180,"d":-90,"when":"","name":"혼주 메이크업·헤어 예약","desc":"양가 어머님 메이크업·헤어를 예약해요.","yes":"예식 당일 시간에 맞춰 준비가 잡혀요.","no":"단골 미용실에서 하시거나 직접 준비하셔도 돼요.","opts":"신부 메이크업샵에 같이 예약 · 출장 · 단골 미용실","tips":["혼주 메이크업은 처음 예산에 없던 항목이 됐다는 후기가 있어요. 누가 낼지 양가와 미리 정해 두세요."]},{"n":"2-21","id":"B-011","p":2,"k":"auto","c":["home!=have"],"b":"h","s":-135,"d":-45,"when":"입주일 45일 전까지","who":"새로 집을 구하는 경우","name":"집 보러 다니기·고르기","desc":"후보 집을 보러 다니고 한 곳을 골라요.","opts":"공인중개사 · 부동산 앱 · 공공임대 신청","tips":["집마다 시세, 권리관계, 보증보험에 가입할 수 있는지를 같이 비교하세요."]},{"n":"2-22","id":"B-024","p":2,"k":"opt","c":[],"b":"w","s":-180,"d":-90,"when":"","name":"지자체 결혼·신혼부부 지원 알아보기","desc":"사는 지역이나 이사 갈 지역에 결혼·신혼부부 지원이 있는지 찾아봐요.","yes":"받을 수 있는 지원을 놓치지 않아요. 거주 기간 조건이 있으면 전입 날짜를 맞출 수 있어요.","no":"혼인신고 뒤 정해진 기간 안에 신청해야 하는 지원은 기한을 놓칠 수 있어요.","opts":"결혼축하금·장려금 · 신혼부부 전세 이자 지원 · 공공임대","tips":["지역에 따라 혼인신고 날 그 지역에 살고 있어야 받는 지원이 있어요. 전입신고를 혼인신고보다 먼저 했다는 후기가 있어요."],"links":[{"label":"정부24 혜택알리미","url":"https://www.gov.kr/portal/rcvfvrSvc/main","note":"","extra":"","date":"2026-11-13"},{"label":"서울시 신혼부부 임차보증금 이자 지원","url":"https://news.seoul.go.kr/citybuild/archives/508747","note":"","extra":"","date":"2026-11-13"}]},{"n":"2-23","id":"B-025","p":2,"k":"opt","c":[],"b":"w","s":-180,"d":-90,"when":"","name":"예비부부 건강검진 (보건소)","desc":"보건소나 지정 의료기관에서 예비부부 기초 검사를 받아요.","yes":"풍진·B형간염·간기능 같은 기초 검사를 결혼 전에 받아 둘 수 있어요.","no":"의무는 아니에요. 원하는 사람만 받아요.","opts":"보건소 · 지정 의료기관 · 병원 검진","tips":["예비부부는 청첩장이나 예식장 계약서를 챙겨 갔다는 후기가 있어요. 예약·공복 여부와 검사 항목은 보건소마다 달라서, 가기 전에 전화로 물어보세요."],"links":[{"label":"예비부부 건강검진 (생활법령정보)","url":"https://easylaw.go.kr/CSP/CsmMain.laf?csmSeq=735","note":"","extra":"","date":"2026-11-13"}]},{"n":"2-24","id":"A+04","p":2,"k":"ask","c":[],"b":"w","s":-150,"d":-90,"when":"","who":"예식장이 메뉴 선택·시식을 해 주는 경우","name":"식사 메뉴 정하기·시식","desc":"하객 식사 메뉴를 고르고, 예식장이 시식을 해 주면 맛봐요.","opts":"시식하고 정하기 · 기본 메뉴 · 메뉴 업그레이드","tips":["메뉴 구성표를 받아 실제 음식과 맞는지 확인하세요. 메뉴 업그레이드 비용과 시식 가능 여부는 계약 때 물어보세요."]},{"n":"2-25","id":"A-024","p":2,"k":"opt","c":[],"b":"w","s":-150,"d":-90,"when":"","name":"뒤풀이 장소 예약","desc":"식이 끝난 뒤 친구들과 따로 모일 장소를 예약해요. 예식장 하객 식사와는 다른 자리예요.","yes":"식 뒤 친구들과 편하게 모일 자리가 생겨요.","no":"예식장 하객 식사로 마무리해요."},{"n":"2-26","id":"A+03","p":2,"k":"opt","c":[],"b":"w","s":-120,"d":-90,"when":"","name":"지인 축사 부탁","desc":"식 중에 축하의 말을 해 줄 친구·지인에게 부탁해요.","yes":"가까운 사람의 축하 말이 식순에 들어가요.","no":"축사 없이 진행해요.","opts":"지인이 직접 쓰기 · 대필 서비스","tools":["flow"],"mc":"축사가 있으면 순서와 축사하는 분 이름을 사회자에게 미리 알려 주세요.","mcDraft":true,"tips":["글을 쓰고 연습할 시간이 필요하니 3달 전쯤 부탁하세요. 길이는 3분 안이 좋아요."]},{"n":"2-27","id":"A+05","p":2,"k":"opt","c":[],"b":"w","s":-120,"d":-90,"when":"","name":"지인 축가 부탁","desc":"축가를 불러 줄 친구·지인에게 부탁해요.","yes":"친구가 곡을 고르고 연습할 시간이 생겨요.","no":"전문 축가만 하거나 축가 없이 진행해요.","opts":"친구·지인 1명 · 듀엣 · 단체 · 신랑·신부 직접","tools":["serenade"],"mc":"3달 전쯤 부탁해야 친구가 곡을 고르고 연습할 수 있어요. 곡과 MR은 사회자에게도 미리 보내 주세요.","mcDraft":true,"tips":["답례로 봉투나 선물을 드리고, 식사와 주차를 챙겨 드리는 경우가 많아요."]},{"n":"2-28","id":"A-023","p":2,"k":"must","c":[],"b":"w","s":-120,"d":-90,"when":"","name":"하객 명단 쓰기","desc":"청첩장을 보낼 사람을 이름으로 정리해요.","opts":"엑셀 · 앱","tips":["관계, 전달 방식, 식사 여부, 전달 담당자 칸을 만들어 두면 청첩장 수량과 보증 인원 계산이 쉬워져요."]},{"n":"2-29","id":"B-012","p":2,"k":"auto","c":["home=jeonse,wolse"],"b":"h","s":-75,"d":-45,"when":"계약하기 전","who":"전세·월세","name":"계약 전 안전 확인","desc":"계약하기 전에 그 집의 권리관계와 집주인 정보를 확인해요.","opts":"직접 확인(인터넷등기소·세움터·실거래가) · 안심전세앱 · HUG 사전한도심사 · 중개사 설명","tips":["등기부등본·건축물대장·실거래가를 직접 보고, 보증보험에 가입할 수 있는 집인지 미리 확인하세요. 보증금이 일정 금액을 넘으면 계약 뒤 입주 전까지 집주인 동의 없이 세무서에서 집주인의 밀린 세금을 볼 수 있어요.","다른 보증기관이 대신 보증금을 돌려준 적이 있는 집주인이면 HUG 보증에 가입할 수 없어요. 안심전세앱 \"안심임대인 조회\"에서 계약 전에 볼 수 있어요."],"links":[{"label":"HUG 전세보증 제도개선 안내(2026-10-30부터)","url":"https://www.khug.or.kr/khmb/m/cc/nn/ccnn000002.jsp?idx=38384&tabIdx=1","note":"","extra":"","date":"2026-11-13"}]},{"n":"2-30","id":"B-013","p":2,"k":"auto","c":["home!=have"],"b":"h","s":-75,"d":-45,"when":"입주일 45일 전","who":"이사하는 경우","name":"집 계약·계약금","desc":"집을 계약하고 계약금을 내요.","opts":"중개사 통해 계약 · 부동산 거래 전자계약","tips":["계약하면 잔금일·입주일이 정해져서 대출·이사·혼수 배송 날짜를 잡을 수 있어요. 잔금 날 등기부를 한 번 더 보세요.","대출이 안 나오거나 보증 가입이 안 되면 계약금을 돌려받고 계약을 없던 일로 한다는 특약(계약서에 따로 적는 약속)을 넣었다는 후기가 많아요.","전입신고 효력은 다음 날 0시에 생겨요. 그래서 \"잔금일 다음 날까지 집주인이 집을 담보로 새 대출(근저당)을 잡지 않는다\"는 특약도 넣었다는 후기가 있어요."]},{"n":"2-31","id":"B-015","p":2,"k":"auto","c":["home!=have","loan=yes"],"b":"h","s":-45,"d":-30,"when":"입주일(잔금일) 30일 전","who":"집 대출 받는 경우","name":"대출 신청","desc":"집 계약 뒤 대출을 신청해 잔금 날에 맞춰 받아요.","opts":"수탁은행 창구 · 은행 앱 · 은행 자체 상품","tips":["정책 대출은 신청 기한이 있어요. 잔금·전입이나 등기 뒤 기한이 지나면 신청할 수 없어요.","심사와 서류 보완에 몇 주가 걸려서, 잔금일 한 달 반 전쯤 은행 상담을 시작했다는 후기가 있어요."],"links":[{"label":"주택도시기금","url":"https://nhuf.molit.go.kr/FP/FP05/FP0502/FP05020401.jsp","note":"","extra":"","date":"2026-11-13"}]},{"n":"2-32","id":"B-022","p":2,"k":"opt","c":[],"b":"w","s":-240,"d":-60,"when":"","name":"혼수 가전 행사 알아보기","desc":"브랜드 혼수 행사·박람회·카드 캐시백을 비교해요.","yes":"결혼·입주 고객 혜택을 받을 수 있어요.","no":"일반 구매가로 사요.","opts":"브랜드 혼수 행사 · 혼수 박람회 · 카드 캐시백","tips":["조건이 달마다 바뀌고 증빙이 필요한 경우가 많아요. 배송이 끝나야 혜택이 들어오는 행사도 있어요."]},{"n":"2-33","id":"A-028","p":2,"k":"opt","c":[],"b":"w","s":-180,"d":-60,"when":"","name":"주례 정하기","desc":"주례를 모실지, 주례 없이 할지 정해요.","yes":"주례사가 식순에 들어가요.","no":"사회자가 진행하고, 부모님 덕담이나 성혼선언으로 그 자리를 채울 수 있어요.","opts":"주례 · 주례 없이(사회자 진행) · 부모님 덕담·성혼선언","tools":["declare","blessing"],"mc":"주례가 없으면 사회자가 식 전체를 이끌어요. 사회자와 같이 정하세요.","mcDraft":true},{"n":"2-34","id":"B-021","p":2,"k":"must","c":[],"b":"h","s":-135,"d":-15,"when":"입주일 15일 전 주문, 배송은 입주일","name":"가전·가구 주문","desc":"고른 가전·가구를 주문하고 배송일을 입주일로 맞춰요.","opts":"매장 · 온라인 · 브랜드 혼수 패키지","tips":["배송일을 입주일에 맞춰야 입주한 뒤 가전 없이 지내는 날이 안 생겨요.","냉장고가 현관을 못 지나 사다리차를 부르거나 돌려보냈다는 후기가 있어요. 주문 전에 현관(방충망 포함)·엘리베이터 폭을 재 두세요."]},{"n":"2-35","id":"A-026","p":2,"k":"auto","c":["a:2-18!=no"],"b":"w","s":-120,"d":-60,"when":"","who":"스튜디오 촬영한 경우","name":"스튜디오 사진 고르기","desc":"촬영한 사진 중 앨범·액자에 넣을 사진을 골라요.","opts":"기본 페이지 안에서 고르기 · 페이지 추가 · 원본 구매","tools":["select","retouch"],"tips":["모바일 청첩장에 쓰려면 예식 2달 전까지 사진을 받아 두세요. 보정본이 3달 걸렸다는 후기도 있으니, 받는 날짜를 셀렉할 때 확인하세요.","셀렉하러 가기 전에 추가 페이지·원본 구매를 어디까지 할지 둘이 정해 가세요."]},{"n":"2-36","id":"B-014","p":2,"k":"auto","c":["home=jeonse,wolse"],"b":"h","s":-45,"d":-15,"when":"계약일부터 기한 안에","who":"전세·월세","name":"임대차 신고·확정일자","desc":"집 계약을 신고하고 확정일자를 받아요.","opts":"온라인·모바일(부동산거래관리시스템) · 주민센터 · 전자계약이면 자동 신고","tips":["기한은 입주일이 아니라 계약일부터 세요. 계약하면 바로 신고하세요. 신고하면서 계약서를 내면 확정일자도 같이 받고, 한쪽만 신고해도 돼요.","전세대출을 받으면 은행에 확정일자 받은 계약서를 내야 해요. 계약하자마자 신고해 두면 대출 서류 준비가 빨라져요."],"links":[{"label":"서울시 주택 임대차 신고 안내","url":"https://news.seoul.go.kr/citybuild/archives/527971","note":"","extra":"","date":"2026-11-13"}]},{"n":"2-37","id":"B-016","p":2,"k":"def","c":["home!=have"],"b":"h","s":-21,"d":-14,"when":"입주일 2~3주 전","who":"새로 집을 구하는 경우","name":"이사업체 예약","desc":"이삿날에 맞춰 이사업체를 예약해요.","opts":"포장이사 · 반포장 · 일반 · 소형(용달)","tips":["허가 업체인지 확인하고, 방문 견적으로 조건을 정하세요. 짐이 파손되면 사진을 찍고 바로 업체에 알리세요.","손 없는 날·주말·월말은 요금이 더 붙고 일찍 마감된다는 후기가 있어요. 입주일이 정해지면 바로 견적부터 받아 두세요."]},{"n":"2-38","id":"B-017","p":2,"k":"ask","c":["home!=have"],"b":"h","s":-30,"d":-1,"when":"입주 전날까지","who":"공사·청소를 업체에 맡기는 경우","name":"인테리어·입주 청소","desc":"입주 전에 공사와 청소를 끝내요.","opts":"인테리어 — 전체 · 부분 / 청소 — 업체 · 직접","tips":["계약서에 자재·규격·공사 기간·하자보수 조건을 적어 두세요.","청소가 끝나고 짐이 들어오기 전, 빈집 상태를 사진·영상으로 남겨 뒀다는 후기가 있어요. 나중에 하자나 원상복구를 따질 때 편해요."]},{"n":"2-39","id":"A-030","p":2,"k":"must","c":[],"b":"w","s":-90,"d":-45,"when":"","name":"청첩장 만들기 (종이·모바일)","desc":"종이 청첩장과 모바일 청첩장을 만들어요.","opts":"종이 + 모바일 · 모바일만 · 종이만 / 부모님용·친구용 따로","tips":["샘플, 시안·교정, 인쇄·배송까지 1~2주를 잡으세요. 인쇄를 승인하면 고칠 수 없으니 날짜·시간, 이름·관계, 모바일 기능 순서로 확인하세요.","수량은 하객 수가 아니라 전달 단위(집·팀)로 세고 여분을 더하세요.","종이 청첩장에 모바일 청첩장 QR을 넣으려면 인쇄 전에 모바일 청첩장 주소부터 만들어 두세요."]},{"n":"2-40","id":"B-019","p":2,"k":"auto","c":["home=jeonse,wolse"],"b":"h","s":-30,"d":0,"when":"입주 전 심사, 전입 뒤 가입","who":"전세·보증금이 큰 월세","name":"전세보증금 반환보증 가입","desc":"집주인이 보증금을 못 돌려줄 때를 대비해 보증에 가입해요.","opts":"HUG · HF(HF 전세대출 이용자) · SGI 서울보증","tips":["HUG는 이사 전에 먼저 심사(사전한도심사)하고, 전입한 뒤 가입을 마치는 방식이에요. HUG 화면에선 상품 이름이 \"전세반환보증\"이에요. 가입한 뒤에도 전입을 유지해야 해요."],"links":[{"label":"HUG 전세보증 제도개선 안내(2026-10-30부터)","url":"https://www.khug.or.kr/khmb/m/cc/nn/ccnn000002.jsp?idx=38384&tabIdx=1","note":"","extra":"","date":"2026-11-13"}]},{"n":"2-41","id":"B+04","p":2,"k":"auto","c":["home!=have"],"b":"h","s":-7,"d":-2,"when":"입주 2~3일 전 신청","who":"이사하는 경우","name":"도시가스 이전 신청","desc":"이사 날 바로 가스를 쓸 수 있게 미리 신청해요.","opts":"지역 도시가스사 고객센터·앱","tips":["가스는 기사님이 집에 와서 열어 줘야 써요. 신청할 때 방문 날짜·시간을 고르니, 집에 사람이 있는 이삿날 시간으로 미리 잡았다는 후기가 있어요."]},{"n":"2-42","id":"B+02","p":2,"k":"ask","c":[],"b":"h","s":-7,"d":0,"when":"같이 살기 시작할 때","who":"차가 있고 배우자도 운전하는 경우","name":"자동차보험 운전자 범위 바꾸기","desc":"배우자도 운전할 수 있게 보험 운전자 범위를 바꿔요.","opts":"부부 한정 · 가족 한정 · 누구나","tips":["부부 한정으로 바꾸면 배우자 운전도 보장돼요. 혼인신고나 같이 살기 전에는 배우자로 인정되지 않을 수 있으니, 바꾸기 전에 보험사에 필요한 서류를 물어보세요."]},{"n":"2-43","id":"B-028","p":2,"k":"opt","c":[],"b":"w","s":-180,"d":-31,"when":"","name":"돈 관리 방식 정하기","desc":"생활비·저축·양가 용돈·대출 상환을 어떻게 나눌지 정해요.","yes":"같이 살기 시작할 때 돈 흐름이 정해져 있어요.","no":"결혼 뒤 상황이 생길 때 정해요.","opts":"한 통장으로 합치기 · 생활비 통장만 같이 · 각자 관리하고 비율로 나누기"},{"n":"2-44","id":"B-029","p":2,"k":"opt","c":[],"b":"w","s":-180,"d":-31,"when":"","name":"결혼 생활 이야기 나누기","desc":"가사·명절·양가 방문·양가 용돈·자녀 계획을 미리 이야기해요.","yes":"같이 살기 전에 서로 기대가 다른 점을 알 수 있어요.","no":"결혼 뒤 그때그때 정해요.","opts":"둘이 대화 · 예비부부 교육 · 상담"},{"n":"2-45","id":"B+03","p":2,"k":"opt","c":[],"b":"w","s":-180,"d":-31,"when":"","name":"통신 결합 할인","desc":"예비부부·가족 결합으로 휴대폰·인터넷 요금 할인을 받아요.","yes":"통신비 결합 할인을 받을 수 있어요. 청첩장이나 계약서로 예비부부 결합이 되는 상품도 있어요.","no":"각자 요금을 내요.","opts":"예비부부 결합 · 혼인신고 뒤 가족 결합","tips":["통신사·상품마다 조건이 달라요. 가입한 통신사에 물어보세요."]},{"n":"2-46","id":"B-030","p":2,"k":"opt","c":[],"b":"w","s":-180,"d":-31,"when":"","name":"예비부부 교육","desc":"지역 가족센터의 예비부부 교실에서 재무·대화·갈등 해결을 배워요.","yes":"재무·대화·갈등 해결을 둘이 같이 배울 수 있어요.","no":"둘이 대화로 정해요.","opts":"서울가족학교 · 사는 곳 가족센터","tips":["구마다 일정이 달라요. 서울은 서울가족포털에서 여러 구 일정을 한 번에 보고 신청했다는 후기가 있어요."],"links":[{"label":"서울가족포털 가족교육(서울가족학교·예비부부교실)","url":"https://familyseoul.or.kr/all-class","note":"","extra":"다른 지역은 사는 곳 가족센터","date":"2026-11-13"}]},{"n":"2-47","id":"B-018","p":2,"k":"auto","c":["home!=have"],"b":"h","s":0,"d":0,"when":"입주일 당일","who":"이사하는 경우","name":"잔금·입주·전입신고","desc":"잔금을 치르고 입주한 날 전입신고를 해요.","opts":"정부24 온라인 · 주민센터 방문","tips":["전세·월세는 이사하고 전입신고를 마친 다음 날부터 보증금을 지킬 힘(대항력)이 생겨요. 확정일자까지 받아 두면 보증금을 먼저 돌려받을 권리도 생겨요. 전입신고는 기한이 있으니 이사한 날 바로 하세요.","잔금 날 큰돈을 보낼 때 이체 한도에 걸려 당황했다는 후기가 많아요. 하루 전까지 한도를 올려 두거나 은행 창구에서 보내세요.","정부24로 저녁 6시 뒤나 토요일·공휴일에 전입신고를 하면 다음 근무시간에 처리돼요. 다음 근무일에 처리됐는지 꼭 확인하세요."],"links":[{"label":"생활법령정보 주택 임대차","url":"https://www.easylaw.go.kr/CSP/CnpClsMain.laf?csmSeq=666&ccfNo=4&cciNo=1&cnpClsNo=1","note":"","extra":"","date":"2026-11-13"},{"label":"정부24 전입신고","url":"https://www.gov.kr/minwon/inc/AA040_form_notice_13100000016.jsp","note":"","extra":"","date":"2026-11-13"}]},{"n":"2-48","id":"B-023","p":2,"k":"ask","c":[],"when":"증여받은 날부터 신고 기한 안에","who":"부모님께 결혼·집 자금을 받는 경우","name":"부모님 지원금 증여 신고","desc":"부모님께 결혼·집 자금을 받으면 증여 신고를 해요.","opts":"현금 · 부동산","tips":["결혼할 때 받는 증여는 기본 공제에 혼인 공제가 더해져요. 혼인 공제는 예식일이 아니라 혼인신고일 앞뒤 기간에 받은 돈이 대상이에요. 배우자 부모님께 받은 돈은 대상이 아니에요.","세무사 없이 홈택스에서 직접 증여세를 신고했다는 후기가 있어요."],"links":[{"label":"상속세및증여세법 제53조의2","url":"https://www.law.go.kr/법령/상속세및증여세법/제53조의2","note":"","extra":"","date":"2026-11-13"}]},{"n":"2-49","id":"B-026","p":2,"k":"opt","c":[],"when":"언제든 (이 시기에 함께 보여 줌)","name":"임신 사전건강관리 검사 지원","desc":"보건소에서 난소기능·정액 검사 비용을 지원받을 수 있어요.","yes":"같은 검사를 지원받아서 받을 수 있어요.","no":"필요할 때 본인 부담으로 받아요.","opts":"e보건소 온라인 · 보건소 방문","tips":["검사 전에 먼저 신청해야 해요. 신청 전에 받은 검사는 지원되지 않아요.","신청한 뒤 정해진 기간 안에 검사하고, 검사 뒤에도 정해진 기간 안에 비용을 청구해야 해요. 지역에 따라 그해 예산이 다 쓰이면 지급이 늦어질 수 있어요."],"links":[{"label":"e보건소 임신 사전건강관리 지원 (사는 곳 보건소도 확인)","url":"https://www.e-health.go.kr/gh/caSrvcGud/selectMdclSupGudInfo.do?heBiz=PG00003&menuId=200097","note":"","extra":"","date":"2026-11-13"}]},{"n":"2-50","id":"B-027","p":2,"k":"ask","c":["a:2-23!=no"],"when":"임신 계획 4주 전까지","who":"검진에서 풍진 항체가 없는 여성","name":"풍진 예방접종","desc":"검진에서 풍진 항체가 없다고 나오면 접종해요.","opts":"보건소 · 병원","tips":["임신 중 풍진 감염을 막으려고 미리 맞아요. 접종 뒤 얼마 동안 임신을 피해야 하는지는 접종하는 곳에서 꼭 물어보세요."],"links":[{"label":"질병관리청 예방접종도우미 「풍진」","url":"https://nip.kdca.go.kr/irhp/infm/goVcntInfo.do?menuLv=1&menuCd=1122","note":"","extra":"","date":"2026-11-13"}]},{"n":"3-01","id":"A-019","p":3,"k":"opt","c":[],"b":"w","s":-180,"d":-30,"when":"","name":"2부 드레스·한복 정하기","desc":"피로연이나 폐백 때 갈아입을 옷을 정해요.","yes":"하객 식사 자리와 폐백에서 다른 분위기의 옷을 입어요.","no":"본식 드레스로 끝까지 가거나 편한 옷으로 갈아입어요.","opts":"컬러·블랙 드레스 대여 · 기성복 구매 · 한복","tips":["드레스 투어 때 같이 보고, 1달 전까지 정하세요. 폐백을 하면 폐백 한복과 겹치는지 보세요."]},{"n":"3-02","id":"A-032","p":3,"k":"opt","c":[],"b":"w","s":-90,"d":-30,"when":"","name":"청첩장 모임","desc":"친구·지인을 직접 만나 청첩장을 건네요.","yes":"얼굴 보고 직접 소식을 전할 수 있어요.","no":"모바일이나 우편으로 전해요.","opts":"식사 모임 · 카페","tools":["table"],"tips":["무리가 많으면 주말 여러 번과 식사비가 생각보다 든다는 후기가 있어요. 몇 번 만날지 먼저 세어 보세요."]},{"n":"3-03","id":"A-036","p":3,"k":"opt","c":[],"b":"w","s":-90,"d":-30,"when":"","name":"답례품 준비","desc":"식사를 못 하는 하객이나 회사 동료에게 드릴 답례품을 정해요.","yes":"식사 대신 답례품을 드릴 수 있어요. 답례품을 받은 하객에게는 식권을 드리지 않는 방식도 있어요.","no":"하객 식사로 대신해요.","opts":"식사 대신 답례품 · 회사 동료용 따로","tips":["외부 답례품을 예식장에 들일 수 있는지 먼저 물어보세요. 하객이 보증 인원보다 덜 왔을 때 남는 식사를 답례품으로 바꿔 주는지도 계약 때 물어보세요."]},{"n":"3-04","id":"A-076","p":3,"k":"opt","c":[],"b":"w","s":-90,"d":-30,"when":"","name":"화동 정하기","desc":"신부 입장 전에 꽃이나 예물을 들고 먼저 입장할 아이를 정해요.","yes":"신부 입장 전에 아이가 먼저 입장해요.","no":"화동 없이 신부가 바로 입장해요.","opts":"친척·지인 아이 · 화동 없이","tools":["flow"],"mc":"화동 보호자께 \"화동이 준비되면 사회자에게 신호를 보내 달라\"고 부탁해 두세요.","tips":["아이 부모님 일정과 아이 옷을 준비할 시간이 필요하니 1달 전까지 부탁하세요."]},{"n":"3-05","id":"A-031","p":3,"k":"must","c":[],"b":"w","s":-60,"d":-30,"when":"","name":"청첩장 전하기","desc":"만나서, 우편으로, 모바일로 청첩장을 전해요.","opts":"직접 만나서 · 우편 · 모바일 · 청첩장 모임","tips":["너무 일찍 보내면 잊히고, 너무 늦으면 일정이 겹쳐요. 1~2달 전이 많아요. 어른께 먼저 드리는 순서를 권하는 안내가 있어요."]},{"n":"3-06","id":"A-033","p":3,"k":"must","c":[],"b":"w","s":-60,"d":-30,"when":"","name":"보증 인원 확정","desc":"하객 수를 확정하고 예식장에 최종 인원을 알려요.","opts":"보증 인원 + 여유 · 양가 따로 세기 · 메뉴 최종 확정","tips":["보증 인원은 하객이 덜 와도 식대를 내는 최소 인원이에요. 모바일 청첩장 참석 회신을 반영하고, 양가 보증을 따로 잡았다면 신랑·신부 하객을 따로 세세요. 알리는 기한은 예식장마다 달라요."]},{"n":"3-07","id":"A-035","p":3,"k":"opt","c":[],"b":"w","s":-60,"d":-30,"when":"","name":"폐백 준비","desc":"폐백을 하면 폐백실과 폐백 음식을 준비해요.","yes":"식이 끝난 뒤 폐백실에서 신랑 측 어른께 인사드려요.","no":"폐백 없이 하객 인사로 마무리해요.","opts":"예식장 폐백실 · 폐백 음식 업체","tips":["예식장에 폐백실이 있는지, 비용은 얼마인지 계약 때 먼저 확인하세요. 폐백용 한복도 필요해요."]},{"n":"3-08","id":"A-037","p":3,"k":"opt","c":[],"b":"w","s":-60,"d":-30,"when":"","name":"부케 받을 사람 정하기","desc":"부케를 받아 줄 친구를 정해 미리 부탁해요.","yes":"부케 던지기를 식순과 원판 촬영에 넣을 수 있어요.","no":"부케 던지기 없이 진행해요.","tips":["부케 받을 사람은 미리 정해 스냅 작가에게 알려 두세요."]},{"n":"3-09","id":"A-038","p":3,"k":"ask","c":[],"b":"w","s":-60,"d":-30,"when":"","who":"먼 지역 하객이 많은 경우","name":"하객 대절 버스","desc":"먼 지역 하객이 함께 타고 올 버스를 예약해요.","opts":"25인승 · 28~35인승 · 40~45인승","tips":["기사님 식대·톨비·주차비·대기 시간이 견적에 들었는지 확인하세요. 여유 좌석을 몇 자리 두세요."]},{"n":"3-10","id":"A-042","p":3,"k":"opt","c":[],"b":"w","s":-60,"d":-30,"when":"","name":"양가 부모님 입장 방식 정하기","desc":"화촉점화나 부모님 입장을 어떻게 할지 정해요.","yes":"부모님이 입장·화촉점화 순서를 미리 아실 수 있어요.","no":"예식장 기본 방식으로 진행하고, 당일 리허설로 맞춰요.","opts":"양가 어머님 화촉점화 · 부모님 함께 입장 · 생략","tools":["parents","cue"],"mc":"화촉점화를 아버님도 같이 하실지, 어머님만 하실지 정해서 알려 주세요. 입장 순서와 멘트가 달라져요.","mcDraft":true,"tips":["식순에 넣기 전에 정하고 부모님께 미리 알려 드리세요. 양가 생각이 다를 수 있어요."]},{"n":"3-11","id":"A-049","p":3,"k":"must","c":[],"b":"w","s":-60,"d":-30,"when":"","name":"축의대 맡아 줄 사람 정하기","desc":"신랑 측·신부 측 축의금과 방명록, 식권을 맡아 줄 사람을 정해요.","opts":"양가 따로 친구·친척 · 축의대 대행 서비스","tips":["그날 일정을 비워 달라는 부탁이라 미리 하는 게 좋아요. 축의금 봉투와 장부는 따로 넘기지 말고 함께 넘겨야 나중에 맞춰 보기 쉬워요."]},{"n":"3-12","id":"A-050","p":3,"k":"opt","c":[],"b":"w","s":-60,"d":-30,"when":"","name":"가방순이 정하기","desc":"예식 날 신부 곁에서 휴대폰과 소지품을 챙겨 줄 사람을 정해요.","yes":"신부 휴대폰·소지품·메이크업 수정 도구를 맡길 사람이 생겨요.","no":"신부가 직접 챙기거나 가족이 나눠 맡아요.","opts":"친구 · 동생·친척","tips":["축의금·귀중품을 누구에게 언제 넘길지 미리 정해 두세요."]},{"n":"3-13","id":"A-077","p":3,"k":"opt","c":[],"b":"w","s":-60,"d":-30,"when":"","name":"웨딩카 준비","desc":"식이 끝난 뒤 숙소나 공항으로 갈 차를 준비해요.","yes":"식 끝나고 바로 이동할 차가 정해져 있어요.","no":"택시나 각자 차로 이동해요.","opts":"렌트 · 지인 차"},{"n":"3-14","id":"B-034","p":3,"k":"auto","c":["home!=have"],"b":"h","s":0,"d":14,"when":"입주 뒤 2주 안","who":"이사하는 경우","name":"주소 바꾸기 (은행·카드·보험·통신)","desc":"새 집 주소로 금융·통신 주소를 바꿔요.","opts":"금융사 앱·영업점 · 전입신고 때 우편물 전송 신청(정부24·주민센터) · 인터넷우체국","tips":["금융 주소를 한 번에 바꿔 주던 서비스는 끝났어요. 전입신고할 때 \"우편물 전입지 전송\"을 함께 신청하면 한동안 옛 주소로 온 우편물을 새 집에서 받아요. 그동안 금융사 앱에서 주소를 하나씩 바꾸세요."],"links":[{"label":"인터넷우체국 주거이전 우편물 전송서비스","url":"https://service.epost.go.kr/front.RetrieveAddressMoveInfo.postal","note":"","extra":"","date":"2026-11-13"}]},{"n":"3-15","id":"A-045","p":3,"k":"opt","c":[],"b":"w","s":-90,"d":-21,"when":"","name":"식전영상 준비","desc":"예식 전에 스크린에 틀 두 사람 영상을 만들어요.","yes":"하객이 자리에 앉아 기다리는 동안 두 사람 이야기를 보여 줄 수 있어요.","no":"영상 없이 예식장 기본 화면으로 가요.","opts":"직접 만들기 · 업체에 맡기기 · 청첩장 업체 무료 제공","tools":["film"],"tips":["예식장 화면 비율과 파일 형식을 먼저 물어보세요. 내는 기한은 예식장마다 달라요."]},{"n":"3-16","id":"A-039","p":3,"k":"must","c":[],"b":"w","s":-60,"d":-21,"when":"","name":"웨딩슈즈·속옷·액세서리 준비","desc":"본식에 신을 구두, 드레스 속옷, 베일·귀걸이를 준비해요.","opts":"구두 — 드레스샵 대여 · 구매 / 속옷 — 누드브라 · 보정속옷 · 살색 속옷 / 베일·귀걸이 — 드레스샵 · 따로 구매","tips":["가봉 전에 굽 높이를 정해야 드레스 기장을 맞출 수 있어요. 당일 갈아신을 납작한 신발도 챙기세요."]},{"n":"3-17","id":"A-046","p":3,"k":"must","c":[],"b":"w","s":-60,"d":-21,"when":"","name":"부케·부토니에 주문","desc":"본식에 들 부케와 신랑 가슴에 꽂을 부토니에를 주문해요.","opts":"생화 · 조화 / 메인 부케 · 던지는 부케 · 부토니에 · 혼주 코사지","tips":["3~4주 전에 주문하세요. 생화는 계절에 따라 원하는 꽃을 못 구할 수 있으니, 그럴 때 어떻게 바꾸는지 주문할 때 물어보세요. 던지는 부케는 따로 맞추기도 해요."]},{"n":"3-18","id":"A-041","p":3,"k":"must","c":[],"b":"w","s":-60,"d":-14,"when":"","name":"식순 정하고 사회자에게 전하기","desc":"식순을 정해 사회자·예식장·스냅 작가에게 전해요.","opts":"기본 식순 · 주례 없는 식순 · 축가·이벤트 넣기 · 짧은 식순","tools":["flow"],"mc":"2주 전까지 식순을 받으면 사회자가 순서마다 멘트와 음악 신호를 맞춰 둘 수 있어요.","mcDraft":true,"tips":["사회자·예식장·작가가 같은 식순표를 들고 있어야 당일 순서가 맞아요. 식순표는 예비로 한 장 더 챙기세요."]},{"n":"3-19","id":"A-043","p":3,"k":"opt","c":[],"b":"w","s":-60,"d":-14,"when":"","name":"예식 음악 정하기 (입장곡·행진곡)","desc":"신랑·신부 입장곡과 행진곡, 식 중 음악을 골라요.","yes":"원하는 곡으로 입장하고 행진해요.","no":"예식장이나 사회자가 쓰는 기본 음악으로 진행해요.","opts":"직접 고르기 · 사회자·음향 담당 추천 · 예식장 기본 · 음원 편집 맡기기","tools":["groom","bride","march","cue"],"mc":"입장곡은 문이 열리는 순간 어느 부분이 나오는지가 중요해요. 몇 초부터 틀지 사회자와 같이 정하세요.","mcDraft":true,"tips":["곡이 정해지면 몇 초부터 틀지까지 정해 두세요. 음원 파일은 1주 전까지 따로 보내요."]},{"n":"3-20","id":"A-044","p":3,"k":"opt","c":[],"b":"w","s":-60,"d":-14,"when":"","name":"혼인서약서·성혼선언문·덕담 준비","desc":"식에서 읽을 혼인서약서, 성혼선언문, 부모님 덕담을 준비해요.","yes":"두 사람과 부모님의 말이 식에 들어가요.","no":"주례사나 사회자의 기본 성혼선언으로 진행해요.","opts":"혼인서약(둘이 낭독) · 성혼선언문 · 부모님 덕담","tools":["vows","declare","blessing"],"mc":"누가 무엇을 읽는지 사회자에게 알려 주세요. 마이크와 순서를 그에 맞춰 준비해요.","mcDraft":true,"tips":["읽는 시간은 3분 안으로 잡으세요. 덕담을 읽으실 부모님께는 연습하실 수 있게 2주 전에 드리세요.","원고는 얼굴을 가리지 않게 가슴 높이로 들고 읽어요."]},{"n":"3-21","id":"B-035","p":3,"k":"ask","c":["trip=abroad"],"b":"t","s":-61,"d":-15,"when":"","who":"허니문 혜택 받는 경우","name":"허니문 혜택 증빙 준비","desc":"리조트·항공사 허니문 혜택에 필요한 서류를 준비해요.","opts":"영문증명서(대법원 전자가족관계등록시스템) · 리조트가 받는 다른 서류(청첩장 등)","tips":["리조트마다 필요한 서류와 결혼 후 인정 기간이 달라요. 예약할 때 물어보세요.","영문 혼인 증명(영문증명서)에는 혼인신고가 등록된 뒤에야 배우자가 나와요. 신고 전이면 리조트가 청첩장 같은 다른 서류를 받아 주는지 물어보세요."]},{"n":"3-22","id":"B-036","p":3,"k":"ask","c":["trip=abroad"],"b":"t","s":-61,"d":-15,"when":"","who":"현지에서 운전하는 경우","name":"국제운전면허증 발급","desc":"신혼여행지에서 렌터카를 운전하려면 국제운전면허증을 받아요.","opts":"운전면허시험장 · 경찰서(일부) · 인천·김해공항 발급센터 · 온라인","tips":["여권, 운전면허증, 사진 1장을 챙기세요. 하와이·이탈리아·스페인처럼 국제운전면허증과 한국 면허증을 같이 가지고 다녀야 하는 곳이 있어요. 나라마다 인정 여부가 달라요."]},{"n":"3-23","id":"A-040","p":3,"k":"def","c":[],"b":"w","s":-45,"d":-14,"when":"","who":"드레스를 빌리는 경우","name":"본식 드레스 가봉","desc":"본식 드레스를 입어 보고 기장과 핏을 맞춰요. 이날 여러 벌을 입어 보고 본식 드레스를 고르기도 해요.","opts":"한 번 · 추가 가봉","tips":["본식에 신을 구두와 당일 입을 속옷을 가져가세요. 걷기, 팔 들기, 인사 자세까지 해 보세요. 마음에 드는 드레스가 없으면 다시 가서 골랐다는 후기가 있어요.","걸을 때 드레스 앞자락을 잡는 연습도 하세요. 키가 아담하거나 비즈 드레스면 생각보다 꽉 잡아야 걷기 편해요."]},{"n":"3-24","id":"A-047","p":3,"k":"must","c":[],"b":"w","s":-30,"d":-14,"when":"","name":"업체별 잔금 일정 정리","desc":"언제, 누구에게, 얼마를 내는지 업체별로 정리해요.","opts":"계좌이체 · 카드 · 현금 봉투(당일 전하는 건 D-day에)","tips":["잔금 날짜는 계약서가 기준이에요. 영수증을 모아 두세요. 카드 할부로 내면 업체가 문을 닫았을 때 남은 할부를 멈출 수 있는 경우가 있어요."]},{"n":"3-25","id":"A-048","p":3,"k":"ask","c":[],"b":"w","s":-30,"d":-14,"when":"","who":"식권을 직접 준비하는 경우","name":"식권 방식 확인·주문","desc":"예식장 식권을 쓸지, 직접 만들지 정하고 주문해요.","opts":"예식장 기본 식권 · 직접 만들기(명함 크기) · 청첩장 업체 서비스","tips":["외부 식권을 받지 않는 홀이 있어요. 만들기 전에 먼저 물어보세요. 오타 고칠 시간까지 2주 전에 주문하세요."]},{"n":"3-26","id":"B-031","p":3,"k":"auto","c":["a:2-14=before"],"b":"w","s":-60,"d":-8,"when":"","who":"식 전에 혼인신고하는 경우","name":"혼인신고 (식 전에 하는 경우)","desc":"시·구청이나 읍·면사무소에 혼인신고서를 내요.","opts":"둘이 방문 · 한 사람만 방문 · 우편","tips":["인터넷으로는 신고할 수 없어요. 방문하거나 우편으로 내요. 신고서에는 두 사람과 성인 증인 두 명의 서명이 필요해요. 한 사람만 가면 안 간 사람의 신분증이나 인감증명서가 필요해요.","처리까지 며칠에서 2주쯤 걸리고 따로 알림이 없었다는 후기가 많아요. 대출 서류에 혼인관계증명서가 필요하면 그 기간을 일정에 넣고, 신고 전에 필요한 증명서를 미리 떼 두세요."],"links":[{"label":"정부24 혼인신고","url":"https://www.gov.kr/mw/AA020InfoCappView.do?CappBizCD=12700000050","note":"","extra":"","date":"2026-11-13"},{"label":"생활법령정보 「혼인신고, 부부가 같이 가야 하나요?」","url":"https://easylaw.go.kr/CSP/EasyLawInfoR.laf?csmSeq=707&easySeq=3103","note":"","extra":"","date":"2026-11-13"}]},{"n":"3-27","id":"B-033","p":3,"k":"must","c":[],"b":"w","s":-60,"d":-8,"when":"","name":"축의금 관리 방식 정하기","desc":"축의금을 양가가 각자 관리할지, 두 사람 몫을 따로 받을지 정해요.","opts":"양가가 각자 관리 · 두 사람 하객 몫만 부부가 받기 · 계좌 입금 안내","tips":["축의금을 누가 받고 식대는 누가 낼지 식 전에 양가와 정해 두세요. 집마다 방법이 달라요.","하객별로 누구 몫인지 기록해 두세요. 부모님 하객 몫을 집 자금에 쓰면 증여로 볼 수 있다는 보도가 있어요."]},{"n":"4-01","id":"A-058","p":4,"k":"opt","c":[],"b":"w","s":-90,"d":-7,"when":"","name":"예단 보내기","desc":"신부 측이 신랑 측에 예단을 보내고, 신랑 측이 봉채(예단을 받고 신부 측에 돌려보내는 돈)를 보내요.","yes":"양가가 전통대로 예를 주고받아요. 규모와 형태는 주로 양가 부모님이 정해요.","no":"예단 없이 진행해요. 생략해도 다른 예물을 주고받는 일이 생길 수 있으니 양가가 미리 맞춰 두세요.","opts":"현금 예단 · 물건 예단(이불·수저·한복 등) · 현금 + 편지"},{"n":"4-02","id":"A-051","p":4,"k":"opt","c":[],"b":"w","s":-14,"d":-7,"when":"","name":"당일 헤어·메이크업 요청 정리","desc":"원하는 헤어와 메이크업을 사진과 함께 담당자에게 미리 전해요.","yes":"원하는 스타일(예: 옆머리 볼륨)을 미리 맞출 수 있어요.","no":"당일 그 자리에서 말하게 돼요. 옆머리 볼륨이나 눈화장 진하기를 더 분명히 말할걸 하고 아쉬워한 후기가 있어요.","opts":"참고 사진 보내기 · 담당 디자이너와 상담"},{"n":"4-03","id":"A-052","p":4,"k":"auto","c":["a:3-25=yes"],"b":"w","s":-14,"d":-7,"when":"","who":"식권을 직접 준비하는 경우","name":"식권 나누기·번호·도장","desc":"식권을 신랑 측·신부 측·어린이·여분으로 나누고 번호와 도장을 찍어요.","opts":"번호 도장 · 손으로 쓰기 · 숫자 스티커","tips":["양가 보증을 따로 잡았다면 신랑·신부 식권을 꼭 따로 세세요. 신랑·신부 도장 색을 다르게 하면 구분이 쉬워요. 예식장이 정한 날까지 식권을 넘기세요."]},{"n":"4-04","id":"A-053","p":4,"k":"auto","c":["or:a:3-11!=no|a:3-12=yes"],"b":"w","s":-14,"d":-7,"when":"","who":"축의대·가방순이를 정한 경우","name":"축의대·가방순이에게 할 일 알려 주기","desc":"축의대와 가방순이를 맡은 분께 당일 할 일을 미리 보내요.","opts":"안내문 종이 · 카톡 메시지","tips":["넣을 것 — 신랑 측·신부 측·여분 식권 봉투 구분, 식권 번호 순서, 봉투 하나에 여러 명일 때 장부 적는 법, 답례품 받은 하객은 식권 없음, 어린이 기준, 식권이 모자랄 때 연락할 사람.","축의대는 일찍 와서 끝까지 있느라 식을 못 봤다는 후기가 있어요. 밥은 언제 먹을지, 사례는 어떻게 할지 같이 알려 주세요."]},{"n":"4-05","id":"A-054","p":4,"k":"opt","c":[],"b":"w","s":-14,"d":-7,"when":"","name":"원판 촬영 명단 정리","desc":"본식 뒤 가족·친지·친구 단체 사진(원판)을 찍을 순서와 사람을 정리해요.","yes":"원판 순서대로 사람을 빠르게 부를 수 있어요.","no":"그 자리에서 사람을 찾아 부르게 돼요. 원판 시간을 미리 계획하지 않아 입장 리허설을 못 했다는 신부도 있었어요."},{"n":"4-06","id":"A-055","p":4,"k":"auto","c":["or:a:1-17=yes|a:1-18=yes"],"b":"w","s":-14,"d":-7,"when":"","who":"스냅·영상을 계약한 경우","name":"스냅·영상 작가에게 요청 보내기","desc":"식순표와 꼭 찍어야 할 사람·장면을 작가에게 보내요.","opts":"식순표 보내기 · 꼭 찍을 사람·장면 목록 · 파일 백업 요청","tips":["식순표, 꼭 찍을 사람·장면(예: 화환), 얼굴 방향을 알려 주고, 촬영 파일 백업도 부탁하세요. 부케 받을 사람도 작가에게 알려 주세요."]},{"n":"4-07","id":"A-056","p":4,"k":"opt","c":[],"b":"w","s":-14,"d":-7,"when":"","name":"부모님께 당일 동선·할 일 알려 드리기","desc":"부모님께 입장 동선, 화촉점화, 인사 순서, 가족사진, 챙길 것을 미리 알려 드려요.","yes":"부모님이 당일 무엇을 하실지 미리 아세요.","no":"예식 직전에 간단히 안내받으시는 경우가 많아요.","opts":"종이·카톡 안내 · 사회자가 당일 설명","tools":["parents","parentsQuiz"],"mc":"부모님 동선은 당일 사회자도 한 번 더 안내해 드려요. 미리 한 번 보시면 당일 덜 낯서세요.","mcDraft":true},{"n":"4-08","id":"A-057","p":4,"k":"must","c":[],"b":"w","s":-14,"d":-7,"when":"","name":"사례비·헬퍼비 봉투 준비","desc":"당일 드릴 봉투를 미리 만들고 겉에 받는 분을 적어 둬요.","opts":"현금 봉투 · 계좌이체","tips":["드레스 헬퍼, 지인 축가, 축의대·가방순이, 주차비처럼 당일 건넬 곳을 한 번에 적어 보세요."]},{"n":"4-09","id":"A-059","p":4,"k":"opt","c":[],"b":"w","s":-14,"d":-7,"when":"","name":"하객 안내 문자","desc":"하객에게 시간·장소·주차·셔틀을 한 번 더 알려요.","yes":"주차장이 멀거나 셔틀을 타야 하는 곳이면 하객이 미리 알고 일찍 나서요.","no":"청첩장 정보만 보고 와요. 주차·셔틀을 모르면 늦게 도착할 수 있어요.","opts":"단체 문자 · 모바일 청첩장 다시 보내기 · 주차·셔틀 안내 넣기"},{"n":"4-10","id":"A-060","p":4,"k":"opt","c":[],"b":"w","s":-14,"d":-7,"when":"","name":"입장 리허설 방식 확인","desc":"예식장이 사전 리허설을 해 주는지, 당일 몇 시에 하는지 물어봐요. 예식장마다 달라요.","yes":"입장 동선과 걸음 속도를 미리 익혀요.","no":"당일 짧게 맞추고 들어가요. 원판 촬영 때문에 리허설을 못 했다는 신부도 있어서, 원판과 리허설 시간을 같이 잡는 게 좋아요.","opts":"예식장 사전 리허설 · 당일 리허설","mc":"드레스 때문에 아버님 걸음이 빠르면 신부가 못 따라가요. 천천히 걸으세요.","tips":["리허설은 보통 예식 30분 전쯤 해요. 예식장마다 다르고, 앞 예식이 늦게 끝나면 밀릴 수 있어요. 맞절과 행진 인사는 둘이 같은 속도로 집에서 미리 연습해 두세요."]},{"n":"4-11","id":"A-066","p":4,"k":"auto","c":["or:a:3-19=yes|a:1-13=yes|a:2-27=yes|a:3-15=yes"],"b":"w","s":-14,"d":-7,"when":"","who":"음악·축가·식전영상을 직접 준비한 경우","name":"음원·영상 파일 보내기","desc":"입장곡·축가 MR·식전영상 파일을 예식장 음향 담당과 사회자에게 보내요.","opts":"미리 보내고 당일 USB도 · 당일 USB만","tips":["식장에는 예식 1주일 전까지 보내는 게 안전해요. USB에도 한 벌 담아 두세요."]},{"n":"4-12","id":"A-061","p":4,"k":"opt","c":[],"b":"w","s":-7,"d":-3,"when":"","name":"부모님 감사 선물·편지","desc":"식 전에 부모님께 드릴 선물이나 편지를 준비해요.","yes":"식 전에 부모님께 감사를 전할 수 있어요.","no":"식 뒤에 따로 전해도 돼요.","opts":"선물 · 편지"},{"n":"4-13","id":"B-037","p":4,"k":"opt","c":["trip=abroad,domestic"],"b":"t","s":-31,"d":-3,"when":"","who":"신혼여행 가는 커플","name":"여행자보험 가입","desc":"신혼여행 동안 아프거나 다칠 때를 대비해 여행자보험에 들어요.","yes":"현지 치료·입원에 대비할 수 있어요. 외교부도 출국 전 가입을 권해요.","no":"현지 병원비를 직접 내요.","opts":"보험사 홈페이지 · 공항 창구 · 보험다모아에서 비교","tips":["휴대품 손해(잃어버린 건 빼고), 항공기·수하물 지연, 여권 재발급 비용 같은 특약을 비교해 보세요."],"links":[{"label":"외교부 해외안전여행","url":"https://0404.go.kr/bbs/bbsPst/MST0000000000026/ATC0000000047498/detail","note":"","extra":"","date":"2026-11-13"}]},{"n":"4-14","id":"B-038","p":4,"k":"opt","c":["trip=abroad"],"b":"t","s":-31,"d":-3,"when":"","who":"해외 신혼여행","name":"환전·해외 결제 카드 준비","desc":"현지에서 쓸 돈과 카드를 준비해요.","yes":"도착하자마자 쓸 결제 수단이 있어요.","no":"현지나 공항에서 환전해요. 출발 1주 전쯤 은행 앱으로 미리 환전하라는 안내가 있어요.","opts":"은행 앱 환전 · 해외 결제 카드 · 신용카드 · 현지 출금"},{"n":"4-15","id":"B-039","p":4,"k":"opt","c":["trip=abroad"],"b":"t","s":-31,"d":-3,"when":"","who":"해외 신혼여행","name":"해외 데이터 준비 (로밍·eSIM·유심)","desc":"현지에서 쓸 데이터를 준비해요.","yes":"도착하자마자 지도와 연락을 쓸 수 있어요.","no":"현지 와이파이나 도착해서 산 유심을 써요.","opts":"통신사 로밍 · eSIM · 현지 유심 · 포켓 와이파이","tips":["eSIM은 휴대폰이 지원하는지 먼저 확인하세요."]},{"n":"4-16","id":"B-041","p":4,"k":"auto","c":["trip=abroad,domestic","when!=date"],"b":"w","s":-14,"d":-2,"when":"","who":"식 직후 떠나는 신혼여행","name":"신혼여행 짐 싸기","desc":"신혼여행 짐을 본식 짐과 따로 미리 싸 둬요.","opts":"여행지·계절별 짐 목록","tools":["pack"],"tips":["식 다음 날 떠나면 식 전 주에 다 싸 두세요. 마지막 주엔 본식 짐까지 겹쳐요."]},{"n":"4-17","id":"A-062","p":4,"k":"ask","c":[],"b":"w","s":-7,"d":-2,"when":"","who":"마지막 가봉을 하는 드레스","name":"마지막 가봉","desc":"본식 직전에 드레스 치수를 한 번 더 맞춰요.","opts":"2~3일 전 방문","tips":["앉았다 일어나 보고, 숨 쉬기 편한지 확인하세요."]},{"n":"4-18","id":"A-063","p":4,"k":"opt","c":[],"b":"w","s":-7,"d":-2,"when":"","name":"네일·페디큐어","desc":"손톱과 발톱을 정리해요.","yes":"반지 교환과 부케 사진에서 손이 깔끔해 보여요.","no":"평소대로 가요.","opts":"베이지·은은한 핑크·시머 화이트 · 셀프"},{"n":"4-19","id":"A-064","p":4,"k":"opt","c":[],"b":"w","s":-7,"d":-2,"when":"","name":"제모·왁싱","desc":"드레스로 드러나는 부분을 정리해요.","yes":"드레스로 드러나는 부분이 정리돼요.","no":"평소대로 가요.","opts":"샵 · 셀프","tips":["면도한 뒤에는 진정 팩을 하고, 알코올이 강한 제품은 피하세요."]},{"n":"4-20","id":"B+06","p":4,"k":"opt","c":["home!=have","trip=abroad,domestic"],"b":"t","s":-8,"d":-2,"when":"","who":"입주한 신혼집을 비우고 떠나는 경우","name":"집 비우는 동안 순찰 신청","desc":"신혼여행으로 집을 비우는 동안 집 주변 순찰을 경찰에 신청해요.","yes":"원하는 날짜·시간에 집 주변을 순찰해 달라고 요청할 수 있어요.","no":"평소대로 집을 비워요.","tips":["경찰민원24 \"순찰신문고\"에서 온라인으로 신청해요. 112 출동이 많으면 순찰을 못 할 수도 있어요."],"links":[{"label":"경찰민원24 순찰신문고","url":"https://minwon24.police.go.kr/cvlcpt/cvlcptGdInfo.do?cvlcptId=MW-914","note":"","extra":"","date":"2026-11-13"}]},{"n":"4-21","id":"A-065","p":4,"k":"opt","c":[],"b":"w","s":-8,"d":-6,"when":"","name":"신랑 헤어컷·다운펌","desc":"본식 일주일쯤 전에 머리를 자르고, 다운펌도 이때 해요. 자르고 일주일쯤 지나야 가장 자연스러워요.","yes":"본식 사진에 맞춰 머리가 정돈돼요.","no":"평소 머리로 가요.","opts":"단골 미용실 · 커트만 · 커트 + 다운펌","tips":["당일 아침엔 면도하고 머리를 감고 가세요. 샵에서 따로 안내하면 그게 우선이에요."]},{"n":"4-22","id":"B-040","p":4,"k":"def","c":["trip=abroad"],"b":"t","s":-5,"d":-2,"when":"","who":"해외 신혼여행","name":"입국 사전 등록·관광세","desc":"가는 나라가 입국 전 온라인 등록이나 관광세를 요구하면 출발 전에 해요.","opts":"몰디브 IMUGA · 태국 TDAC · 인도네시아(발리) 도착카드·관광세 · 일본 Visit Japan Web · 칸쿤 Visitax","tips":["도착 며칠 전부터 등록이 열리는 곳이 많아요. 식 다음 날 떠나면 예식 주간에 열리니, 열리면 바로 하세요.","입국 신고(몰디브 IMUGA · 발리 도착카드)는 공식 사이트에서 무료예요. 돈을 받는 비슷한 사이트는 쓰지 마세요."],"links":[{"label":"나라마다 출발 전 공식 안내에서 확인하세요. 예: 몰디브 이민청","url":"https://immigration.gov.mv/visa/tourist-visa","note":"","extra":"","date":"2026-11-13"}]},{"n":"5-01","id":"A-069","p":5,"k":"must","c":[],"b":"w","s":-14,"d":-1,"when":"","name":"본식 가방 싸기","desc":"예식 날 들고 갈 물건을 한 가방에 챙겨요.","tips":["전날 밤 현관 한곳에 모아 두고, 알람을 여러 개 맞추고 일찍 주무세요. 반지, 혼인서약서, 사례비 봉투, 음원 USB를 마지막으로 확인하세요.","신랑 구두와 니플패치도 따로 한 번 더 보세요."]},{"n":"5-02","id":"A-068","p":5,"k":"must","c":[],"b":"w","s":-7,"d":-1,"when":"","name":"당일 타임테이블 확인·공유","desc":"메이크업, 이동, 예식장 도착, 촬영 시간을 한 장으로 정리해 공유해요.","opts":"양가 가족에게 공유 · 사회자·플래너에게 공유","mc":"타임테이블을 사회자에게도 보내 주세요. 도착 시간과 미팅 시간을 거기에 맞춰요.","mcDraft":true,"tips":["메이크업·헬퍼·이동·예식장·촬영 업체가 같은 시간표로 움직여야 늦어지지 않아요. 양가 가족에게도 보내세요.","식 끝나고 하객 인사·폐백·정산까지 시간표에 넣으세요. 생각보다 오래 걸렸다는 후기가 있어요."]},{"n":"5-03","id":"A-070","p":5,"k":"opt","c":[],"b":"w","s":-7,"d":-1,"when":"","name":"포토테이블 소품 챙기기","desc":"예식장 입구 포토테이블에 놓을 사진과 소품을 챙겨요.","yes":"하객이 입구에서 두 사람 사진을 보며 기다려요.","no":"포토테이블 없이 가요.","opts":"웨딩 포스터 · 액자 · 조화·캔들 · 청첩장","tips":["예식장이 사진만 받아 액자로 꾸며 주는 곳도 있어요. 무엇을 가져가야 하는지 먼저 물어보세요. 챙길 게 있으면 전날 차에 미리 실어 두세요."]},{"n":"5-04","id":"B-042","p":5,"k":"opt","c":["trip=abroad,domestic"],"b":"t","s":-2,"d":-1,"when":"","who":"신혼여행 가는 커플","name":"온라인 체크인·좌석 확인","desc":"항공사 웹이나 앱으로 미리 체크인하고 좌석을 확인해요.","yes":"공항 수속 시간을 줄일 수 있어요.","no":"공항 카운터에서 수속해요.","opts":"웹·앱 체크인 · 자동 체크인","tips":["체크인 시작·마감 시간은 항공사와 노선마다 달라요. 항공사 앱에서 확인하세요."]},{"n":"6-01","id":"A-071","p":6,"k":"must","c":[],"b":"w","s":0,"d":0,"when":"","name":"축의금·식권·방명록 주고받기","desc":"식 전에 축의대 담당에게 식권과 장부를 넘기고, 식이 끝나면 축의금 가방을 받아요.","opts":"신랑 측·신부 측 따로 · 한 곳","tips":["봉투는 그 자리에서 열지 말고 순서대로 모았다가, 두 사람 이상이 같이 열어 장부와 맞추게 해 주세요.","식이 끝나면 정해 둔 가족이 축의금 가방을 바로 받아, 들고 다니지 말고 차처럼 잠기는 곳에 두세요."]},{"n":"6-02","id":"A-072","p":6,"k":"must","c":[],"b":"w","s":0,"d":0,"when":"","name":"사례비·헬퍼비 전하기","desc":"미리 만든 봉투를 받는 분께 건네요.","opts":"직접 · 부모님이나 가방순이에게 맡기기","tips":["예식장 잔금은 계약서에 적힌 날에 내요."]},{"n":"6-03","id":"A-073","p":6,"k":"opt","c":[],"b":"w","s":0,"d":0,"when":"","name":"신랑·신부 식사·컨디션 챙기기","desc":"긴 하루를 버틸 수 있게 먹고 쉬는 것을 챙겨요.","yes":"든든히 먹고, 물은 적게, 드레스 입기 전에 화장실을 다녀오세요. 간식은 초콜릿보다 한입에 먹는 사탕처럼 혀에 색이 안 드는 걸로 챙기세요.","no":"예식 내내 배고프고 지칠 수 있어요. 식 중엔 거의 못 먹고 끝나고 가족과 먹었다는 후기가 있어요.","opts":"간식·물·빨대 챙기기 · 식 끝나고 식사 자리 확인"},{"n":"6-04","id":"A-074","p":6,"k":"auto","c":["a:3-25=yes"],"b":"w","s":0,"d":0,"when":"","who":"식권으로 식대를 정산하는 예식장","name":"식권 정산 맞춰 보기","desc":"받은 식권에서 남은 식권을 빼서 나눠 준 장수를 구하고, 예식장 식사 인원과 맞춰 봐요.","opts":"나눠 준 장수로 계산 · 걷어 온 장수로 계산","tips":["걷어 온 식권에 우리 도장이 찍혀 있는지, 어린이 구분이 맞는지 보세요. 예식장이 나눠 준 장수로 계산하는지, 걷어 온 장수로 계산하는지는 계약 때 적어 두세요."]},{"n":"6-05","id":"B+07","p":6,"k":"auto","c":["trip=abroad,domestic","when=same"],"b":"w","s":0,"d":0,"when":"","who":"식 당일 출국하는 경우","name":"식 끝나고 공항으로 이동","desc":"식장에서 공항까지 이동할 차와 짐을 챙겨요.","opts":"당일 출발 · 공항 근처 1박 뒤 출발","tips":["신혼여행 짐은 미리 차에 실어 두세요. 폐백·하객 인사·식장 정산까지 생각보다 오래 걸렸다는 후기가 있어요. 비행기 시간을 넉넉히 띄우세요.","신부 머리핀과 화장을 어디서 정리할지 정해 두세요(집·근처 숙소·공항). 공항이나 기내에서 핀을 뺐다는 후기가 있어요."]},{"n":"7-01","id":"A-078","p":7,"k":"must","c":[],"b":"w","s":0,"d":1,"when":"","name":"감사 인사 보내기","desc":"와 주신 하객과 축의금을 보내 주신 분께 감사 인사를 전해요.","opts":"단체 감사 문자 · 축의만 보낸 분께 기프티콘 · 멀리서 온 분께 교통비 · 감사 카드","tools":["thanks"],"tips":["단체 문자는 식 당일 밤이나 다음 날 오전에 보내는 게 좋아요. 사회나 축가를 해 준 분께는 식 당일이나 다음 날 바로 연락하는 게 가장 좋아요."]},{"n":"7-02","id":"A-079","p":7,"k":"must","c":[],"b":"w","s":1,"d":14,"when":"","name":"축의금 정리","desc":"누가 얼마를 보냈는지 장부로 정리해요.","opts":"엑셀 장부 · 방명록·봉투 사진 · 앱","tips":["하객 명단과 축의 기록을 맞춰 두면 감사 인사와 나중의 경조사 때 찾기 쉬워요. 방명록·장부·봉투는 버리지 말고 사진과 함께 보관하세요. 부모님 몫과 두 사람 몫을 나눈 근거가 돼요."]},{"n":"7-03","id":"B-043","p":7,"k":"auto","c":["a:2-14!=before"],"b":"w","s":1,"d":30,"when":"","who":"식 후에 신고하는 경우","name":"혼인신고 (식 후에 하는 경우)","desc":"시·구청이나 읍·면사무소에 혼인신고서를 내요.","opts":"둘이 방문 · 한 사람만 방문 · 우편","tips":["신고하기 전에는 법률상 배우자가 아니라서 배우자 공제 같은 제도를 받을 수 없어요. 인터넷으로는 신고할 수 없고, 방문하거나 우편으로 내요. 혼인세액공제·혼인지원금이 2027년부터 어떻게 될지는 12월 국회에서 결정될 예정이에요.","동네 주민센터가 아니라 시·구청이나 읍·면사무소에 내요. 주민센터에 갔다가 구청으로 다시 갔다는 후기가 있어요."],"links":[{"label":"정부24 혼인신고","url":"https://www.gov.kr/mw/AA020InfoCappView.do?CappBizCD=12700000050","note":"","extra":"","date":"2026-11-13"}]},{"n":"7-04","id":"A-080","p":7,"k":"opt","c":[],"b":"w","s":1,"d":14,"when":"","name":"회사 답례","desc":"직장 동료에게 따로 답례를 해요.","yes":"함께 일하는 분들께 따로 감사를 전할 수 있어요.","no":"감사 인사만 돌리는 경우도 있어요.","opts":"답례품 · 신혼여행 기념품 · 감사 인사만","tips":["회사마다 관례가 달라요. 부서 전체에 돌리는 곳도, 팀과 축의해 준 분만 챙기는 곳도 있으니 먼저 결혼한 동료에게 물어보세요."]},{"n":"7-05","id":"A-081","p":7,"k":"ask","c":[],"b":"w","s":1,"d":7,"when":"","who":"옷을 빌린 경우","name":"빌린 옷 돌려주기","desc":"빌린 2부 드레스·한복·예복을 돌려줘요.","opts":"직접 반납 · 업체 수거","tips":["반납 날짜와 방법은 업체마다 달라요. 빌릴 때 받은 안내를 확인하세요."]},{"n":"7-06","id":"A-083","p":7,"k":"opt","c":[],"b":"w","s":1,"d":14,"when":"","name":"가족·지인에게 사진 보내기","desc":"식 사진을 가족과 지인에게 보내요.","yes":"사진을 기다리던 가족·지인이 받아 봐요.","no":"업체 원본은 몇 달 걸리기도 해요. 사진을 늦게 보내 \"왜 이제야?\"라는 말에 민망했다는 신부도 있었어요.","opts":"원본 공유 링크 · 골라서 보내기"},{"n":"7-07","id":"A-082","p":7,"k":"auto","c":["or:a:1-17=yes|a:1-18=yes"],"b":"w","s":30,"d":120,"when":"","who":"스냅·영상을 계약한 경우","name":"본식 사진·영상 받기·고르기","desc":"본식 원본을 받아 앨범에 넣을 사진을 고르고, 수정본과 앨범을 받아요.","opts":"원본만 · 고르기 → 수정본 → 앨범","tools":["select","retouch"],"tips":["업체마다 받는 기간이 크게 달라요. 원본이 오기까지 두 달 넘게 걸렸다는 후기가 있어요. 계약할 때 원본·수정본·앨범을 각각 언제 받는지 물어 두세요."]},{"n":"7-08","id":"B-044","p":7,"k":"auto","c":["a:3-21=yes"],"when":"혼인신고 뒤, 출발 전","who":"허니문 혜택 등 혼인 증빙이 필요한 경우","name":"영문 혼인 증명(영문증명서) 받기","desc":"리조트 혜택이나 해외 서류에 쓸 영문 혼인 증명서를 받아요.","tips":["대법원 전자가족관계등록시스템에서 \"영문증명서\"로 받아요. 이름은 여권의 영문 이름으로 나와요. 혼인신고가 등록된 뒤에야 배우자가 나와서, 식 끝나고 신고하고 바로 떠나면 출발 전에 받기 어려워요."],"links":[{"label":"대법원 전자가족관계등록시스템","url":"https://efamily.scourt.go.kr/","note":"","extra":"","date":"2026-11-13"}]},{"n":"7-09","id":"B-045","p":7,"k":"auto","c":["tax"],"when":"혼인신고한 다음 해 연말정산·종합소득세 신고 때","who":"해당 기간에 혼인신고한 경우","name":"혼인세액공제 받기","desc":"혼인신고를 한 해의 세금에서 결혼 공제를 받아요.","opts":"연말정산 · 종합소득세 신고 · 경정청구","tips":["혼인신고만 하면 저절로 들어가지 않아요. 연말정산이나 종합소득세 신고 때 직접 넣고, 놓쳤으면 경정청구로 받을 수 있어요. 낼 세금이 없으면 공제 효과도 없어요. 2027년부터 어떻게 될지는 12월 국회에서 결정될 예정이에요."],"links":[{"label":"국세청 혼인세액공제","url":"https://www.nts.go.kr/nts/cm/cntnts/cntntsView.do?cntntsId=7875","note":"","extra":"","date":"2026-11-13"}]},{"n":"7-10","id":"B-046","p":7,"k":"hide","c":[],"when":"","who":"확정되면 넣기","name":"혼인지원금 신청","desc":"(확정되면) 혼인신고한 부부에게 주는 지원금을 신청해요."},{"n":"7-11","id":"B-047","p":7,"k":"ask","c":[],"when":"혼인신고한 해의 연말정산","who":"배우자 소득이 적은 경우","name":"연말정산 배우자 공제","desc":"배우자 소득이 일정 금액 이하면 연말정산 때 배우자를 공제 대상으로 올려요.","opts":"연말정산 · 경정청구","tips":["결혼식 날이 아니라 그해 12월 31일에 혼인신고가 돼 있는지로 판단해요. 배우자가 결혼 전에 번 그해 소득도 합쳐서 보니, 소득 기준은 회사 연말정산 안내나 국세청에서 확인하세요."],"links":[{"label":"소득세법 제53조(공제 대상 판정 시기)","url":"https://www.law.go.kr/법령/소득세법/제53조","note":"","extra":"","date":"2026-11-13"}]},{"n":"7-12","id":"B-049","p":7,"k":"auto","c":["a:2-22=yes"],"when":"혼인신고 뒤, 지역마다 기한 있음","who":"지자체 지원 대상인 경우","name":"지자체 결혼 지원금 신청","desc":"사는 지역의 결혼축하금·장려금을 신청해요.","opts":"지자체 누리집 · 주민센터","tips":["혼인신고 뒤 정해진 기간 안에 신청해야 하는 곳이 있어요. 신청할 때 혼인관계증명서가 필요해서, 신고가 처리된 걸 확인하고 바로 신청했다는 후기가 있어요."],"links":[{"label":"정부24 혜택알리미","url":"https://www.gov.kr/portal/rcvfvrSvc/main","note":"","extra":"","date":"2026-11-13"}]},{"n":"7-13","id":"B+01","p":7,"k":"ask","c":[],"when":"혼인신고 뒤","who":"결혼 전 든 사망 보장 보험이 있는 경우","name":"보험 수익자 확인","desc":"결혼 전에 든 보험의 사망보험금 받는 사람(수익자)을 배우자로 바꿀지 정해요.","opts":"수익자 바꾸기 · 그대로 두기","tips":["수익자를 부모님처럼 특정한 사람으로 정해 뒀다면 결혼해도 그대로예요. \"법정상속인\"으로 돼 있으면 혼인신고 뒤 배우자도 상속인에 들어가요. 보험사 앱이나 고객센터에서 지금 수익자를 먼저 확인하세요."]},{"n":"7-14","id":"B-050","p":7,"k":"opt","c":[],"when":"혼인신고 뒤","name":"청약통장 점검","desc":"결혼 뒤 두 사람 청약통장을 어떻게 쓸지 확인해요.","yes":"배우자 통장 가입 기간을 청약 가점에 일부 더할 수 있는지 알 수 있어요.","no":"지금 통장 그대로 둬요.","opts":"그대로 유지 · 넣는 돈 조정","links":[{"label":"청약홈 청약 가점 계산기","url":"https://www.applyhome.co.kr/ap/apg/selectAddpntCalculatorView.do","note":"","extra":"","date":"2026-11-13"}]},{"n":"7-15","id":"B-051","p":7,"k":"ask","c":[],"when":"혼인신고 뒤","who":"결혼 전 각자 집이 한 채씩 있는 경우","name":"혼인 2주택 양도세 특례 확인","desc":"결혼으로 집이 두 채가 됐을 때 세금 특례를 받을 수 있는지 확인해요.","tips":["혼인신고일부터 정해진 기간 안에 먼저 파는 집을 1세대 1주택으로 볼 수 있어요. 파는 집도 보유 기간 같은 비과세 조건은 따로 갖춰야 해요. 결혼 전에 이미 한쪽이 두 채 넘게 가졌다면 대상이 아니에요. 세무서에 꼭 확인하세요."],"links":[{"label":"소득세법 시행령 제155조 제5항","url":"https://www.law.go.kr/법령/소득세법시행령/제155조","note":"","extra":"","date":"2026-11-13"}]},{"n":"7-16","id":"B+05","p":7,"k":"opt","c":["home!=have"],"when":"입주 뒤","name":"집들이","desc":"가족·지인을 신혼집에 초대해요.","yes":"가족·지인에게 신혼집을 보여 줄 수 있어요.","no":"밖에서 따로 만나 인사해요.","opts":"양가 · 친구 · 회사"}],"taxEnd":"2026-12-31","kakao":"https://open.kakao.com/o/sN9YLHVi"};
